export const MIGRATIONS: { name: string; sql: string }[] = [
  { name: "0001_foundation.sql", sql: "-- FC도착 0001 — 역할·스키마·기본 권한\n--\n-- 왜 public 이 아니라 fcd 스키마인가:\n--   Supabase 는 public 스키마에 새 표가 생길 때마다 anon·authenticated 에게\n--   권한 전부(arwdDxtm)를 붙이는 기본 ACL 을 갖고 있고, public 은 REST(PostgREST)로\n--   밖에 열려 있다. fcd 스키마는 REST 에 노출되지 않고, 기본 권한도 여기서 걷는다.\n--\n-- 왜 anon·authenticated 가 아니라 fcd_public·fcd_user 인가:\n--   서버만 DB 에 붙는다. 브라우저는 Supabase 토큰을 받지 않는다. 서버는 요청마다\n--   트랜잭션 안에서 `set local role` 로 이 두 역할 중 하나가 되어 RLS 를 그대로 받는다.\n--   두 역할은 PostgREST 의 authenticator 에 부여되지 않으므로 밖에서 쓸 수 없다.\n\ndo $$\nbegin\n  if not exists (select 1 from pg_roles where rolname = 'fcd_public') then\n    create role fcd_public nologin noinherit;\n  end if;\n  if not exists (select 1 from pg_roles where rolname = 'fcd_user') then\n    create role fcd_user nologin noinherit;\n  end if;\nend $$;\n\n-- 마이그레이션을 돌리는 역할(로컬=postgres 슈퍼유저, Supabase=postgres)이 set role 할 수 있게\ndo $$\nbegin\n  execute format('grant fcd_public to %I', current_user);\n  execute format('grant fcd_user to %I', current_user);\nexception when others then\n  -- 슈퍼유저는 부여 없이도 set role 이 된다\n  null;\nend $$;\n\ncreate schema if not exists fcd;\nrevoke all on schema fcd from public;\ngrant usage on schema fcd to fcd_public, fcd_user;\n\n-- 기본 ACL 걷기: 이 스키마에 앞으로 생기는 표·함수·시퀀스에 아무도 자동 권한을 받지 않는다.\nalter default privileges in schema fcd revoke all on tables from public;\nalter default privileges in schema fcd revoke all on sequences from public;\nalter default privileges in schema fcd revoke all on functions from public;\n\ndo $$\ndeclare r text;\nbegin\n  foreach r in array array['anon', 'authenticated', 'service_role'] loop\n    if exists (select 1 from pg_roles where rolname = r) then\n      execute format('alter default privileges in schema fcd revoke all on tables from %I', r);\n      execute format('alter default privileges in schema fcd revoke all on sequences from %I', r);\n      execute format('alter default privileges in schema fcd revoke all on functions from %I', r);\n      execute format('revoke all on schema fcd from %I', r);\n    end if;\n  end loop;\nend $$;\n\n-- 요청 문맥 ------------------------------------------------------------------\n\ncreate or replace function fcd.uid() returns uuid\nlanguage sql stable as $$\n  select nullif(current_setting('app.user_id', true), '')::uuid\n$$;\n\ncreate or replace function fcd.demo_on() returns boolean\nlanguage sql stable as $$\n  select coalesce(current_setting('app.demo_mode', true), 'off') = 'on'\n$$;\n\ngrant execute on function fcd.uid() to fcd_public, fcd_user;\ngrant execute on function fcd.demo_on() to fcd_public, fcd_user;\n" },
  { name: "0002_tables.sql", sql: "-- FC도착 0002 — 표\n-- 규칙: 데모 자료는 is_demo 조직 아래에만 있고, 조직 아래 모든 것은 ON DELETE CASCADE 로 매달린다.\n-- 규칙: 요금표·응찰·청구서·상태 이력·등급·감사·설정은 고치지 않고 새 줄(새 판)을 쌓는다.\n\n-- 참조 ----------------------------------------------------------------------\n\ncreate table fcd.hubs (\n  code text primary key,\n  name_ko text not null,\n  name_zh text not null,\n  province_ko text not null,\n  lat double precision not null,\n  lng double precision not null,\n  stage smallint not null default 1 check (stage between 1 and 3),\n  ord smallint not null default 0\n);\n\ncreate table fcd.ports (\n  code text primary key,\n  name_ko text not null,\n  name_zh text not null,\n  lat double precision not null,\n  lng double precision not null,\n  ord smallint not null default 0\n);\n\ncreate table fcd.modes (\n  code text primary key check (code in ('LCL', 'FERRY', 'FCL', 'AIR')),\n  name_ko text not null,\n  name_zh text not null,\n  days_min smallint not null,\n  days_max smallint not null,\n  ord smallint not null default 0,\n  check (days_min <= days_max)\n);\n\ncreate table fcd.fc_centers (\n  code text primary key,\n  name text not null,\n  region text not null,\n  km_incheon integer not null,\n  km_pyeongtaek integer not null\n);\n\ncreate table fcd.segments (\n  code text primary key,\n  ord smallint not null unique,\n  name_ko text not null,\n  name_zh text not null,\n  description_ko text not null\n);\n\ncreate table fcd.cargo_traits (\n  code text primary key,\n  name_ko text not null,\n  name_zh text not null,\n  verdict_ko text not null,\n  requirement_ko text not null,\n  needs_capability boolean not null default false,\n  blocked_modes text[] not null default '{}',\n  ord smallint not null default 0\n);\n\n-- 설정은 새 판으로 쌓는다. 현재값 = 키별 가장 최근 줄.\ncreate table fcd.settings (\n  id uuid primary key default gen_random_uuid(),\n  key text not null,\n  value jsonb not null,\n  note text,\n  created_by uuid,\n  created_at timestamptz not null default now()\n);\ncreate index settings_key_idx on fcd.settings (key, created_at desc);\n\ncreate table fcd.duty_rates (\n  id uuid primary key default gen_random_uuid(),\n  category text not null,\n  name_ko text not null,\n  rate_bp integer not null check (rate_bp between 0 and 10000),\n  note text,\n  created_by uuid,\n  created_at timestamptz not null default now()\n);\ncreate index duty_rates_cat_idx on fcd.duty_rates (category, created_at desc);\n\n-- 조직·사람 ------------------------------------------------------------------\n\ncreate table fcd.orgs (\n  id uuid primary key default gen_random_uuid(),\n  kind text not null check (kind in ('shipper', 'partner', 'platform')),\n  name text not null,\n  name_zh text,\n  slug text unique,\n  is_demo boolean not null default false,\n  status text not null default 'active'\n    check (status in ('active', 'public_info', 'pending_verification', 'official', 'deletion_requested', 'deleted')),\n  business_type text\n    check (business_type in ('forwarder', 'consolidator', 'ferry_agent', 'air_forwarder', 'customs_broker', 'fulfillment_3pl')),\n  biz_reg_no text,\n  license_no text,\n  cargo_insurance text,\n  related_party_note text,\n  logo_path text,\n  hq_city text,\n  address text,\n  phone text,\n  website text,\n  intro text,\n  public_source text,\n  public_checked_on date,\n  default_locale text not null default 'ko' check (default_locale in ('ko', 'zh')),\n  created_at timestamptz not null default now()\n);\ncreate index orgs_kind_idx on fcd.orgs (kind, status);\n\ncreate table fcd.org_hubs (\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  hub text not null references fcd.hubs (code),\n  primary key (org_id, hub)\n);\n\ncreate table fcd.org_modes (\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  mode text not null references fcd.modes (code),\n  primary key (org_id, mode)\n);\n\ncreate table fcd.org_capabilities (\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  trait text not null references fcd.cargo_traits (code),\n  primary key (org_id, trait)\n);\n\n-- 사람은 반드시 소속 조직(home_org) 하나에 매달린다 — 조직을 지우면 사람도 사라진다.\n-- id 는 Supabase Auth 의 사용자 id 와 같다(외래키는 걸지 않는다: 로컬 PGlite 에는 auth 스키마가 없다).\ncreate table fcd.profiles (\n  id uuid primary key,\n  home_org_id uuid not null references fcd.orgs (id) on delete cascade,\n  email text not null unique,\n  name text not null,\n  phone text,\n  locale text not null default 'ko' check (locale in ('ko', 'zh')),\n  created_at timestamptz not null default now()\n);\n\ncreate table fcd.memberships (\n  user_id uuid not null references fcd.profiles (id) on delete cascade,\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  role text not null\n    check (role in ('shipper_admin', 'shipper_member', 'partner_admin', 'partner_member', 'platform_admin')),\n  created_at timestamptz not null default now(),\n  primary key (user_id, org_id)\n);\n\n-- Supabase Auth 를 안 쓸 때(로컬·시험)만 쓰는 비밀번호 해시\ncreate table fcd.local_credentials (\n  user_id uuid primary key references fcd.profiles (id) on delete cascade,\n  password_hash text not null,\n  created_at timestamptz not null default now()\n);\n\n-- 요금표 ---------------------------------------------------------------------\n\ncreate table fcd.rate_cards (\n  id uuid primary key default gen_random_uuid(),\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  card_no text not null,\n  version integer not null default 1 check (version >= 1),\n  supersedes_id uuid references fcd.rate_cards (id) on delete cascade,\n  origin_hub text not null references fcd.hubs (code),\n  port text not null references fcd.ports (code),\n  mode text not null references fcd.modes (code),\n  valid_from date not null,\n  valid_to date not null,\n  certainty text not null check (certainty in ('confirmed', 'estimated', 'extra_possible')),\n  fuel_surcharge_separate boolean not null default false,\n  is_public_price boolean not null default false,\n  transit_days_min smallint not null,\n  transit_days_max smallint not null,\n  status text not null default 'active' check (status in ('active', 'withdrawn')),\n  change_note text,\n  created_by uuid,\n  created_at timestamptz not null default now(),\n  unique (card_no, version),\n  check (valid_from <= valid_to),\n  check (transit_days_min <= transit_days_max)\n);\ncreate index rate_cards_lane_idx on fcd.rate_cards (origin_hub, port, mode);\ncreate index rate_cards_org_idx on fcd.rate_cards (org_id);\ncreate unique index rate_cards_one_successor on fcd.rate_cards (supersedes_id) where supersedes_id is not null;\n\ncreate table fcd.rate_card_lines (\n  id uuid primary key default gen_random_uuid(),\n  rate_card_id uuid not null references fcd.rate_cards (id) on delete cascade,\n  segment text not null references fcd.segments (code),\n  included boolean not null,\n  basis text not null check (basis in ('per_cbm', 'per_rt', 'per_kg', 'per_chargeable_kg', 'per_carton', 'per_unit',\n                                       'per_pallet', 'per_container', 'per_shipment', 'percent_goods')),\n  unit_price numeric(14, 2) not null check (unit_price >= 0),\n  currency text not null check (currency in ('KRW', 'RMB', 'USD')),\n  min_charge numeric(14, 2) check (min_charge >= 0),\n  certainty text not null check (certainty in ('confirmed', 'estimated', 'extra_possible')),\n  note text\n);\ncreate index rate_card_lines_card_idx on fcd.rate_card_lines (rate_card_id);\n\ncreate table fcd.rate_card_tiers (\n  id uuid primary key default gen_random_uuid(),\n  rate_card_id uuid not null references fcd.rate_cards (id) on delete cascade,\n  segment text not null references fcd.segments (code),\n  min_qty numeric(12, 3) not null check (min_qty >= 0),\n  discount_bp integer not null check (discount_bp between 0 and 9000)\n);\ncreate index rate_card_tiers_card_idx on fcd.rate_card_tiers (rate_card_id);\n\n-- 화주 ---------------------------------------------------------------------\n\ncreate table fcd.skus (\n  id uuid primary key default gen_random_uuid(),\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  name text not null,\n  preset text,\n  hs_category text not null default 'general',\n  units integer not null check (units > 0),\n  cartons integer not null check (cartons > 0),\n  kg numeric(12, 2) not null check (kg > 0),\n  cbm numeric(12, 3) not null check (cbm > 0),\n  goods_value numeric(14, 2) not null check (goods_value >= 0),\n  goods_currency text not null default 'RMB' check (goods_currency in ('KRW', 'RMB', 'USD')),\n  traits text[] not null default '{}',\n  target_price integer,\n  archived boolean not null default false,\n  created_by uuid,\n  created_at timestamptz not null default now()\n);\ncreate index skus_org_idx on fcd.skus (org_id);\n\ncreate table fcd.quote_requests (\n  id uuid primary key default gen_random_uuid(),\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  req_no text not null unique,\n  title text not null,\n  sku_id uuid references fcd.skus (id) on delete set null,\n  units integer not null check (units > 0),\n  cartons integer not null check (cartons > 0),\n  kg numeric(12, 2) not null check (kg > 0),\n  cbm numeric(12, 3) not null check (cbm > 0),\n  goods_value numeric(14, 2) not null,\n  goods_currency text not null check (goods_currency in ('KRW', 'RMB', 'USD')),\n  hs_category text not null default 'general',\n  traits text[] not null default '{}',\n  origin_hub text not null references fcd.hubs (code),\n  port text not null references fcd.ports (code),\n  mode text references fcd.modes (code),\n  fc_code text not null references fcd.fc_centers (code),\n  ready_on date not null,\n  bid_deadline timestamptz not null,\n  status text not null default 'open' check (status in ('open', 'selected', 'cancelled')),\n  note text,\n  created_by uuid,\n  created_at timestamptz not null default now()\n);\ncreate index quote_requests_org_idx on fcd.quote_requests (org_id, created_at desc);\ncreate index quote_requests_lane_idx on fcd.quote_requests (origin_hub, port);\n\ncreate table fcd.quote_request_events (\n  id uuid primary key default gen_random_uuid(),\n  request_id uuid not null references fcd.quote_requests (id) on delete cascade,\n  kind text not null,\n  detail text,\n  actor_id uuid,\n  created_at timestamptz not null default now()\n);\ncreate index qre_req_idx on fcd.quote_request_events (request_id, created_at);\n\n-- 응찰 — 9구간 금액 스냅숏. 고치지 않고 새 판(version, supersedes_id)으로.\ncreate table fcd.bids (\n  id uuid primary key default gen_random_uuid(),\n  request_id uuid not null references fcd.quote_requests (id) on delete cascade,\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  bid_no text not null,\n  version integer not null default 1,\n  supersedes_id uuid references fcd.bids (id) on delete cascade,\n  rate_card_id uuid references fcd.rate_cards (id) on delete set null,\n  kind text not null check (kind in ('auto', 'adjusted')),\n  mode text not null references fcd.modes (code),\n  amounts jsonb not null,\n  certainties jsonb not null,\n  total bigint not null check (total >= 0),\n  confirmed_total bigint not null check (confirmed_total >= 0),\n  transit_days_min smallint not null,\n  transit_days_max smallint not null,\n  valid_until timestamptz not null,\n  status text not null default 'submitted' check (status in ('submitted', 'withdrawn')),\n  note text,\n  created_by uuid,\n  created_at timestamptz not null default now(),\n  unique (bid_no, version)\n);\ncreate index bids_req_idx on fcd.bids (request_id);\ncreate index bids_org_idx on fcd.bids (org_id);\ncreate unique index bids_one_successor on fcd.bids (supersedes_id) where supersedes_id is not null;\n\ncreate table fcd.bookings (\n  id uuid primary key default gen_random_uuid(),\n  booking_no text not null unique,\n  request_id uuid not null references fcd.quote_requests (id) on delete cascade,\n  bid_id uuid not null references fcd.bids (id) on delete cascade,\n  shipper_org_id uuid not null references fcd.orgs (id) on delete cascade,\n  partner_org_id uuid not null references fcd.orgs (id) on delete cascade,\n  created_by uuid,\n  created_at timestamptz not null default now(),\n  unique (request_id)\n);\n\ncreate table fcd.shipments (\n  id uuid primary key default gen_random_uuid(),\n  shipment_no text not null unique,\n  booking_id uuid not null references fcd.bookings (id) on delete cascade,\n  shipper_org_id uuid not null references fcd.orgs (id) on delete cascade,\n  partner_org_id uuid not null references fcd.orgs (id) on delete cascade,\n  origin_hub text not null references fcd.hubs (code),\n  port text not null references fcd.ports (code),\n  mode text not null references fcd.modes (code),\n  fc_code text not null references fcd.fc_centers (code),\n  units integer not null,\n  cartons integer not null,\n  kg numeric(12, 2) not null,\n  cbm numeric(12, 3) not null,\n  stage smallint not null default 1 check (stage between 1 and 9),\n  etd date,\n  eta_fc date,\n  delivered_at timestamptz,\n  fc_returned_units integer not null default 0 check (fc_returned_units >= 0),\n  created_at timestamptz not null default now()\n);\ncreate index shipments_shipper_idx on fcd.shipments (shipper_org_id);\ncreate index shipments_partner_idx on fcd.shipments (partner_org_id);\n\n-- 상태 이력 — 표준 9단계 + 업체가 쓰는 원래 상태값. 쌓기만 한다.\ncreate table fcd.shipment_events (\n  id uuid primary key default gen_random_uuid(),\n  shipment_id uuid not null references fcd.shipments (id) on delete cascade,\n  stage smallint not null check (stage between 1 and 9),\n  raw_status text,\n  note text,\n  occurred_at timestamptz not null,\n  created_by uuid,\n  created_at timestamptz not null default now()\n);\ncreate index shipment_events_idx on fcd.shipment_events (shipment_id, occurred_at);\n\ncreate table fcd.exceptions (\n  id uuid primary key default gen_random_uuid(),\n  shipment_id uuid not null references fcd.shipments (id) on delete cascade,\n  kind text not null check (kind in ('customs_hold', 'inspection', 'fc_rejected', 'ferry_cancelled', 'billing_deviation')),\n  note text not null,\n  opened_at timestamptz not null default now(),\n  resolved_at timestamptz,\n  resolution text,\n  created_by uuid\n);\ncreate index exceptions_ship_idx on fcd.exceptions (shipment_id);\n\ncreate table fcd.documents (\n  id uuid primary key default gen_random_uuid(),\n  shipment_id uuid not null references fcd.shipments (id) on delete cascade,\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  kind text not null check (kind in ('commercial_invoice', 'packing_list', 'bl', 'co', 'import_declaration', 'photo', 'other')),\n  file_name text not null,\n  storage_path text,\n  size_bytes integer,\n  created_by uuid,\n  created_at timestamptz not null default now()\n);\ncreate index documents_ship_idx on fcd.documents (shipment_id);\n\n-- 청구서 — 9구간 스냅숏. 정정은 새 판.\ncreate table fcd.invoices (\n  id uuid primary key default gen_random_uuid(),\n  invoice_no text not null,\n  version integer not null default 1,\n  supersedes_id uuid references fcd.invoices (id) on delete cascade,\n  shipment_id uuid not null references fcd.shipments (id) on delete cascade,\n  partner_org_id uuid not null references fcd.orgs (id) on delete cascade,\n  amounts jsonb not null,\n  total bigint not null check (total >= 0),\n  note text,\n  issued_on date not null,\n  created_by uuid,\n  created_at timestamptz not null default now(),\n  unique (invoice_no, version)\n);\ncreate index invoices_ship_idx on fcd.invoices (shipment_id);\ncreate unique index invoices_one_successor on fcd.invoices (supersedes_id) where supersedes_id is not null;\n\ncreate table fcd.reviews (\n  id uuid primary key default gen_random_uuid(),\n  shipment_id uuid not null unique references fcd.shipments (id) on delete cascade,\n  shipper_org_id uuid not null references fcd.orgs (id) on delete cascade,\n  partner_org_id uuid not null references fcd.orgs (id) on delete cascade,\n  rating smallint not null check (rating between 1 and 5),\n  on_time_ok boolean not null,\n  billing_ok boolean not null,\n  body text not null,\n  author_label text not null,\n  published boolean not null default true,\n  created_by uuid,\n  created_at timestamptz not null default now()\n);\ncreate index reviews_partner_idx on fcd.reviews (partner_org_id);\n\ncreate table fcd.notifications (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references fcd.profiles (id) on delete cascade,\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  kind text not null check (kind in ('bid_arrived', 'deadline_soon', 'exception', 'invoice_arrived', 'booking', 'status', 'system')),\n  title text not null,\n  body text,\n  link text,\n  read_at timestamptz,\n  created_at timestamptz not null default now()\n);\ncreate index notifications_user_idx on fcd.notifications (user_id, created_at desc);\n\ncreate table fcd.notification_prefs (\n  user_id uuid not null references fcd.profiles (id) on delete cascade,\n  kind text not null,\n  in_app boolean not null default true,\n  email boolean not null default false,\n  sms boolean not null default false,\n  kakao boolean not null default false,\n  primary key (user_id, kind)\n);\n\n-- 운영 ---------------------------------------------------------------------\n\ncreate table fcd.verification_requests (\n  id uuid primary key default gen_random_uuid(),\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  requester_name text not null,\n  requester_email text not null,\n  requester_phone text,\n  message text,\n  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),\n  decided_at timestamptz,\n  decided_by uuid,\n  decision_note text,\n  created_at timestamptz not null default now()\n);\n\ncreate table fcd.deletion_requests (\n  id uuid primary key default gen_random_uuid(),\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  requester_name text not null,\n  requester_email text not null,\n  reason text not null,\n  status text not null default 'pending' check (status in ('pending', 'done', 'rejected')),\n  decided_at timestamptz,\n  decided_by uuid,\n  decision_note text,\n  created_at timestamptz not null default now()\n);\n\ncreate table fcd.grade_records (\n  id uuid primary key default gen_random_uuid(),\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  grade text not null check (grade in ('fc_ready')),\n  granted boolean not null,\n  basis jsonb not null,\n  note text,\n  created_by uuid,\n  created_at timestamptz not null default now()\n);\ncreate index grade_records_org_idx on fcd.grade_records (org_id, created_at desc);\n\ncreate table fcd.ad_slots (\n  id uuid primary key default gen_random_uuid(),\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  lane_hub text references fcd.hubs (code),\n  lane_port text references fcd.ports (code),\n  starts_on date not null,\n  ends_on date not null,\n  status text not null default 'active' check (status in ('active', 'ended')),\n  created_by uuid,\n  created_at timestamptz not null default now(),\n  check (starts_on <= ends_on)\n);\n\ncreate table fcd.audit_log (\n  id uuid primary key default gen_random_uuid(),\n  actor_id uuid,\n  org_id uuid references fcd.orgs (id) on delete cascade,\n  action text not null,\n  target text,\n  detail jsonb,\n  created_at timestamptz not null default now()\n);\ncreate index audit_log_idx on fcd.audit_log (created_at desc);\n" },
  { name: "0003_access.sql", sql: "-- FC도착 0003 — 누가 무엇을 보는가 (RLS)\n--\n-- 원칙\n--   · 모든 표에 RLS 를 켠다. 정책이 없으면 아무도 못 본다.\n--   · 어떤 역할에도 DELETE 권한이 없다 — 예외는 조직의 거점·방식·취급 능력·알림 설정(편집용 연결표).\n--   · 요금표·응찰·청구서·상태 이력·등급·감사·설정에는 UPDATE 권한이 없다 — 새 판으로만 쌓인다.\n--   · DEMO_MODE=off 면 데모 조직과 그 아래 전부가 안 보인다. 운영자는 늘 본다(화면에 표시가 붙는다).\n\n-- 도움 함수 — 정책 안에서 RLS 가 되돌아 걸리지 않게 security definer 로.\n\ncreate or replace function fcd.my_org_ids() returns setof uuid\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select org_id from fcd.memberships where user_id = fcd.uid()\n$$;\n\ncreate or replace function fcd.is_member(o uuid) returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select exists (select 1 from fcd.memberships where user_id = fcd.uid() and org_id = o)\n$$;\n\ncreate or replace function fcd.is_org_admin(o uuid) returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select exists (\n    select 1 from fcd.memberships\n    where user_id = fcd.uid() and org_id = o and role in ('shipper_admin', 'partner_admin', 'platform_admin')\n  )\n$$;\n\ncreate or replace function fcd.is_platform() returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select exists (\n    select 1 from fcd.memberships m join fcd.orgs o on o.id = m.org_id\n    where m.user_id = fcd.uid() and m.role = 'platform_admin' and o.kind = 'platform'\n  )\n$$;\n\ncreate or replace function fcd.org_visible(o uuid) returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select fcd.is_platform() or fcd.demo_on() or not coalesce((select is_demo from fcd.orgs where id = o), false)\n$$;\n\ncreate or replace function fcd.org_kind(o uuid) returns text\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select kind from fcd.orgs where id = o\n$$;\n\ncreate or replace function fcd.org_status(o uuid) returns text\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select status from fcd.orgs where id = o\n$$;\n\n-- 공개 면에 실리는 업체 상태\ncreate or replace function fcd.partner_listed(o uuid) returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select exists (\n    select 1 from fcd.orgs\n    where id = o and kind = 'partner' and status in ('public_info', 'pending_verification', 'official')\n  ) and fcd.org_visible(o)\n$$;\n\n-- 요금을 낼 수 있는 업체 상태(공식 + 인증 대기)\ncreate or replace function fcd.partner_priced(o uuid) returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select exists (\n    select 1 from fcd.orgs where id = o and kind = 'partner' and status in ('pending_verification', 'official')\n  ) and fcd.org_visible(o)\n$$;\n\n-- 두 조직 사이에 예약이 있는가(화주 이름은 예약 뒤에만 물류사에 보인다)\ncreate or replace function fcd.has_booking_with(o uuid) returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select exists (\n    select 1 from fcd.bookings b\n    where (b.shipper_org_id = o and b.partner_org_id in (select fcd.my_org_ids()))\n       or (b.partner_org_id = o and b.shipper_org_id in (select fcd.my_org_ids()))\n  )\n$$;\n\n-- 행 값으로 판정 — 자기 표의 읽기 정책은 이쪽을 쓴다.\n-- (INSERT … RETURNING 때 같은 문장이 넣은 새 행은 id 로 다시 찾아도 보이지 않는다)\ncreate or replace function fcd.request_row_visible(p_org uuid, p_id uuid, p_status text, p_hub text) returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select fcd.org_visible(p_org) and (\n    fcd.is_member(p_org)\n    or fcd.is_platform()\n    or exists (select 1 from fcd.bids b where b.request_id = p_id and b.org_id in (select fcd.my_org_ids()))\n    or (p_status = 'open' and exists (\n          select 1 from fcd.org_hubs h\n          where h.hub = p_hub and h.org_id in (select fcd.my_org_ids()) and fcd.partner_priced(h.org_id)))\n  )\n$$;\n\ncreate or replace function fcd.can_see_request(r uuid) returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select exists (\n    select 1 from fcd.quote_requests q\n    where q.id = r and fcd.request_row_visible(q.org_id, q.id, q.status, q.origin_hub)\n  )\n$$;\n\ncreate or replace function fcd.shipment_row_visible(p_shipper uuid, p_partner uuid) returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select fcd.org_visible(p_shipper) and fcd.org_visible(p_partner)\n    and (fcd.is_member(p_shipper) or fcd.is_member(p_partner) or fcd.is_platform())\n$$;\n\ncreate or replace function fcd.can_see_shipment(s uuid) returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select exists (\n    select 1 from fcd.shipments x\n    where x.id = s and fcd.shipment_row_visible(x.shipper_org_id, x.partner_org_id)\n  )\n$$;\n\ncreate or replace function fcd.is_shipment_partner(s uuid) returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select exists (select 1 from fcd.shipments x where x.id = s and fcd.is_member(x.partner_org_id))\n$$;\n\ncreate or replace function fcd.is_shipment_shipper(s uuid) returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select exists (select 1 from fcd.shipments x where x.id = s and fcd.is_member(x.shipper_org_id))\n$$;\n\n-- 화주 조직 소속인가(요금표 전체는 화주만 본다 — 물류사끼리는 서로의 비공개 요금을 못 본다)\ncreate or replace function fcd.i_am_shipper() returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select exists (\n    select 1 from fcd.memberships m join fcd.orgs o on o.id = m.org_id\n    where m.user_id = fcd.uid() and o.kind = 'shipper' and fcd.org_visible(o.id)\n  )\n$$;\n\ncreate or replace function fcd.rate_card_row_visible(p_org uuid, p_public boolean, p_status text) returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select fcd.org_visible(p_org) and (\n    fcd.is_member(p_org) or fcd.is_platform()\n    or (fcd.i_am_shipper() and fcd.partner_priced(p_org))\n    or (p_public and fcd.partner_priced(p_org) and p_status = 'active')\n  )\n$$;\n\ncreate or replace function fcd.can_see_rate_card(c uuid) returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select exists (\n    select 1 from fcd.rate_cards r\n    where r.id = c and fcd.rate_card_row_visible(r.org_id, r.is_public_price, r.status)\n  )\n$$;\n\ndo $$\ndeclare f text;\nbegin\n  foreach f in array array[\n    'my_org_ids()', 'is_member(uuid)', 'is_org_admin(uuid)', 'is_platform()', 'org_visible(uuid)',\n    'org_kind(uuid)', 'org_status(uuid)', 'partner_listed(uuid)', 'partner_priced(uuid)',\n    'has_booking_with(uuid)', 'can_see_request(uuid)', 'can_see_shipment(uuid)',\n    'is_shipment_partner(uuid)', 'is_shipment_shipper(uuid)', 'can_see_rate_card(uuid)', 'i_am_shipper()',\n    'request_row_visible(uuid, uuid, text, text)', 'shipment_row_visible(uuid, uuid)', 'rate_card_row_visible(uuid, boolean, text)'\n  ] loop\n    execute format('revoke all on function fcd.%s from public', f);\n    execute format('grant execute on function fcd.%s to fcd_public, fcd_user', f);\n  end loop;\nend $$;\n\n-- RLS 켜기: fcd 스키마의 모든 표 ----------------------------------------------\ndo $$\ndeclare t text;\nbegin\n  for t in select tablename from pg_tables where schemaname = 'fcd' loop\n    execute format('alter table fcd.%I enable row level security', t);\n  end loop;\nend $$;\n\n-- 참조: 누구나 읽는다 --------------------------------------------------------\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['hubs', 'ports', 'modes', 'fc_centers', 'segments', 'cargo_traits', 'settings', 'duty_rates'] loop\n    execute format('grant select on fcd.%I to fcd_public, fcd_user', t);\n    execute format('create policy %I on fcd.%I for select to fcd_public, fcd_user using (true)', t || '_read', t);\n  end loop;\nend $$;\n\ngrant insert on fcd.settings, fcd.duty_rates to fcd_user;\ncreate policy settings_write on fcd.settings for insert to fcd_user with check (fcd.is_platform());\ncreate policy duty_rates_write on fcd.duty_rates for insert to fcd_user with check (fcd.is_platform());\n\n-- 조직 -----------------------------------------------------------------------\ngrant select on fcd.orgs to fcd_public, fcd_user;\ngrant insert, update on fcd.orgs to fcd_user;\ncreate policy orgs_public on fcd.orgs for select to fcd_public using (fcd.partner_listed(id));\ncreate policy orgs_user on fcd.orgs for select to fcd_user using (\n  fcd.org_visible(id) and (\n    fcd.is_member(id) or fcd.is_platform() or fcd.partner_listed(id) or fcd.has_booking_with(id)\n  )\n);\ncreate policy orgs_insert on fcd.orgs for insert to fcd_user with check (fcd.is_platform());\ncreate policy orgs_update on fcd.orgs for update to fcd_user\n  using (fcd.is_org_admin(id) or fcd.is_platform())\n  with check (fcd.is_org_admin(id) or fcd.is_platform());\n\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['org_hubs', 'org_modes', 'org_capabilities'] loop\n    execute format('grant select on fcd.%I to fcd_public, fcd_user', t);\n    execute format('grant insert, delete on fcd.%I to fcd_user', t);\n    execute format('create policy %I on fcd.%I for select to fcd_public using (fcd.partner_listed(org_id))', t || '_public', t);\n    execute format('create policy %I on fcd.%I for select to fcd_user using (fcd.org_visible(org_id) and (fcd.is_member(org_id) or fcd.is_platform() or fcd.partner_listed(org_id)))', t || '_user', t);\n    execute format('create policy %I on fcd.%I for insert to fcd_user with check (fcd.is_org_admin(org_id) or fcd.is_platform())', t || '_insert', t);\n    execute format('create policy %I on fcd.%I for delete to fcd_user using (fcd.is_org_admin(org_id) or fcd.is_platform())', t || '_delete', t);\n  end loop;\nend $$;\n\n-- 사람 -----------------------------------------------------------------------\ngrant select, update on fcd.profiles to fcd_user;\ncreate policy profiles_read on fcd.profiles for select to fcd_user using (\n  id = fcd.uid() or fcd.is_platform() or (fcd.is_member(home_org_id) and fcd.org_visible(home_org_id))\n);\ncreate policy profiles_update on fcd.profiles for update to fcd_user\n  using (id = fcd.uid()) with check (id = fcd.uid());\n\ngrant select on fcd.memberships to fcd_user;\ncreate policy memberships_read on fcd.memberships for select to fcd_user using (\n  user_id = fcd.uid() or fcd.is_member(org_id) or fcd.is_platform()\n);\n-- local_credentials: 어떤 요청 역할에도 권한 없음(서버 시스템 경로만).\n\n-- 요금표 — 수정 권한 없음, 새 판만 --------------------------------------------\ngrant select on fcd.rate_cards, fcd.rate_card_lines, fcd.rate_card_tiers to fcd_public, fcd_user;\ngrant insert on fcd.rate_cards, fcd.rate_card_lines, fcd.rate_card_tiers to fcd_user;\ncreate policy rate_cards_read on fcd.rate_cards for select to fcd_public, fcd_user using (fcd.rate_card_row_visible(org_id, is_public_price, status));\ncreate policy rate_cards_insert on fcd.rate_cards for insert to fcd_user with check (\n  fcd.is_member(org_id) and fcd.org_kind(org_id) = 'partner' and fcd.org_status(org_id) <> 'deleted'\n);\ncreate policy rate_card_lines_read on fcd.rate_card_lines for select to fcd_public, fcd_user using (fcd.can_see_rate_card(rate_card_id));\ncreate policy rate_card_lines_insert on fcd.rate_card_lines for insert to fcd_user with check (\n  exists (select 1 from fcd.rate_cards r where r.id = rate_card_id and fcd.is_member(r.org_id))\n);\ncreate policy rate_card_tiers_read on fcd.rate_card_tiers for select to fcd_public, fcd_user using (fcd.can_see_rate_card(rate_card_id));\ncreate policy rate_card_tiers_insert on fcd.rate_card_tiers for insert to fcd_user with check (\n  exists (select 1 from fcd.rate_cards r where r.id = rate_card_id and fcd.is_member(r.org_id))\n);\n\n-- SKU -----------------------------------------------------------------------\ngrant select, insert, update on fcd.skus to fcd_user;\ncreate policy skus_read on fcd.skus for select to fcd_user using (\n  fcd.org_visible(org_id) and (fcd.is_member(org_id) or fcd.is_platform())\n);\ncreate policy skus_insert on fcd.skus for insert to fcd_user with check (fcd.is_member(org_id) and fcd.org_kind(org_id) = 'shipper');\ncreate policy skus_update on fcd.skus for update to fcd_user using (fcd.is_member(org_id)) with check (fcd.is_member(org_id));\n\n-- 견적 요청 ------------------------------------------------------------------\ngrant select, insert, update on fcd.quote_requests to fcd_user;\ncreate policy qr_read on fcd.quote_requests for select to fcd_user using (fcd.request_row_visible(org_id, id, status, origin_hub));\ncreate policy qr_insert on fcd.quote_requests for insert to fcd_user with check (\n  fcd.is_member(org_id) and fcd.org_kind(org_id) = 'shipper'\n);\ncreate policy qr_update on fcd.quote_requests for update to fcd_user\n  using (fcd.is_member(org_id)) with check (fcd.is_member(org_id));\n\ngrant select, insert on fcd.quote_request_events to fcd_user;\ncreate policy qre_read on fcd.quote_request_events for select to fcd_user using (fcd.can_see_request(request_id));\ncreate policy qre_insert on fcd.quote_request_events for insert to fcd_user with check (fcd.can_see_request(request_id));\n\n-- 응찰 — 수정 권한 없음 --------------------------------------------------------\ngrant select, insert on fcd.bids to fcd_user;\ncreate policy bids_read on fcd.bids for select to fcd_user using (\n  fcd.org_visible(org_id) and (\n    fcd.is_member(org_id) or fcd.is_platform()\n    or exists (select 1 from fcd.quote_requests q where q.id = request_id and fcd.is_member(q.org_id))\n  )\n);\ncreate policy bids_insert on fcd.bids for insert to fcd_user with check (\n  fcd.is_member(org_id) and fcd.partner_priced(org_id) and fcd.can_see_request(request_id)\n);\n\n-- 예약·선적 ------------------------------------------------------------------\ngrant select, insert on fcd.bookings to fcd_user;\ncreate policy bookings_read on fcd.bookings for select to fcd_user using (\n  fcd.org_visible(shipper_org_id) and fcd.org_visible(partner_org_id) and\n  (fcd.is_member(shipper_org_id) or fcd.is_member(partner_org_id) or fcd.is_platform())\n);\ncreate policy bookings_insert on fcd.bookings for insert to fcd_user with check (fcd.is_member(shipper_org_id));\n\ngrant select, insert, update on fcd.shipments to fcd_user;\ncreate policy shipments_read on fcd.shipments for select to fcd_user using (fcd.shipment_row_visible(shipper_org_id, partner_org_id));\ncreate policy shipments_insert on fcd.shipments for insert to fcd_user with check (fcd.is_member(shipper_org_id));\ncreate policy shipments_update on fcd.shipments for update to fcd_user\n  using (fcd.is_member(partner_org_id) or fcd.is_platform())\n  with check (fcd.is_member(partner_org_id) or fcd.is_platform());\n\ngrant select, insert on fcd.shipment_events to fcd_user;\ncreate policy se_read on fcd.shipment_events for select to fcd_user using (fcd.can_see_shipment(shipment_id));\ncreate policy se_insert on fcd.shipment_events for insert to fcd_user with check (\n  fcd.is_shipment_partner(shipment_id) or fcd.is_platform()\n  or (stage = 1 and fcd.is_shipment_shipper(shipment_id))\n);\n\ngrant select, insert, update on fcd.exceptions to fcd_user;\ncreate policy ex_read on fcd.exceptions for select to fcd_user using (fcd.can_see_shipment(shipment_id));\ncreate policy ex_insert on fcd.exceptions for insert to fcd_user with check (fcd.can_see_shipment(shipment_id));\ncreate policy ex_update on fcd.exceptions for update to fcd_user\n  using (fcd.is_shipment_partner(shipment_id) or fcd.is_platform())\n  with check (fcd.is_shipment_partner(shipment_id) or fcd.is_platform());\n\ngrant select, insert on fcd.documents to fcd_user;\ncreate policy docs_read on fcd.documents for select to fcd_user using (fcd.can_see_shipment(shipment_id));\ncreate policy docs_insert on fcd.documents for insert to fcd_user with check (\n  fcd.is_member(org_id) and fcd.can_see_shipment(shipment_id)\n);\n\n-- 청구서 — 수정 권한 없음 ------------------------------------------------------\ngrant select, insert on fcd.invoices to fcd_user;\ncreate policy inv_read on fcd.invoices for select to fcd_user using (fcd.can_see_shipment(shipment_id));\ncreate policy inv_insert on fcd.invoices for insert to fcd_user with check (\n  fcd.is_member(partner_org_id) and fcd.is_shipment_partner(shipment_id)\n);\n\n-- 평가 -----------------------------------------------------------------------\ngrant select on fcd.reviews to fcd_public, fcd_user;\ngrant insert on fcd.reviews to fcd_user;\ncreate policy reviews_public on fcd.reviews for select to fcd_public using (published and fcd.partner_listed(partner_org_id));\ncreate policy reviews_user on fcd.reviews for select to fcd_user using (\n  fcd.org_visible(shipper_org_id) and fcd.org_visible(partner_org_id) and\n  ((published and fcd.partner_listed(partner_org_id)) or fcd.is_member(shipper_org_id) or fcd.is_member(partner_org_id) or fcd.is_platform())\n);\ncreate policy reviews_insert on fcd.reviews for insert to fcd_user with check (\n  fcd.is_member(shipper_org_id) and fcd.is_shipment_shipper(shipment_id)\n);\n\n-- 알림 -----------------------------------------------------------------------\ngrant select, update on fcd.notifications to fcd_user;\ncreate policy notif_read on fcd.notifications for select to fcd_user using (user_id = fcd.uid() and fcd.org_visible(org_id));\ncreate policy notif_update on fcd.notifications for update to fcd_user using (user_id = fcd.uid()) with check (user_id = fcd.uid());\n\ngrant select, insert, update, delete on fcd.notification_prefs to fcd_user;\ncreate policy np_all on fcd.notification_prefs for all to fcd_user using (user_id = fcd.uid()) with check (user_id = fcd.uid());\n\n-- 운영 큐 — 공개 면에서 접수, 운영자가 처리 ------------------------------------------\ngrant insert on fcd.verification_requests, fcd.deletion_requests to fcd_public, fcd_user;\ngrant select, update on fcd.verification_requests, fcd.deletion_requests to fcd_user;\ncreate policy vr_insert on fcd.verification_requests for insert to fcd_public, fcd_user\n  with check (status = 'pending' and decided_at is null and fcd.partner_listed(org_id));\ncreate policy vr_read on fcd.verification_requests for select to fcd_user using (fcd.is_platform());\ncreate policy vr_update on fcd.verification_requests for update to fcd_user using (fcd.is_platform()) with check (fcd.is_platform());\ncreate policy dr_insert on fcd.deletion_requests for insert to fcd_public, fcd_user\n  with check (status = 'pending' and decided_at is null and fcd.partner_listed(org_id));\ncreate policy dr_read on fcd.deletion_requests for select to fcd_user using (fcd.is_platform());\ncreate policy dr_update on fcd.deletion_requests for update to fcd_user using (fcd.is_platform()) with check (fcd.is_platform());\n\ngrant select on fcd.grade_records, fcd.ad_slots to fcd_public, fcd_user;\ngrant insert on fcd.grade_records, fcd.ad_slots to fcd_user;\ngrant update on fcd.ad_slots to fcd_user;\ncreate policy gr_read on fcd.grade_records for select to fcd_public, fcd_user using (fcd.org_visible(org_id));\ncreate policy gr_insert on fcd.grade_records for insert to fcd_user with check (fcd.is_platform());\ncreate policy ads_read on fcd.ad_slots for select to fcd_public, fcd_user using (fcd.org_visible(org_id));\ncreate policy ads_insert on fcd.ad_slots for insert to fcd_user with check (fcd.is_platform());\ncreate policy ads_update on fcd.ad_slots for update to fcd_user using (fcd.is_platform()) with check (fcd.is_platform());\n\ngrant select, insert on fcd.audit_log to fcd_user;\ncreate policy audit_insert on fcd.audit_log for insert to fcd_user with check (actor_id = fcd.uid());\ncreate policy audit_read on fcd.audit_log for select to fcd_user using (fcd.is_platform());\n" },
  { name: "0004_views.sql", sql: "-- FC도착 0004 — 보기(view)\n-- security_invoker 보기: 부르는 사람의 RLS 를 그대로 받는다.\n-- 집계 보기(v_partner_metrics, v_market_counts): 소유자 권한으로 전체를 세되,\n--   조직 단위로 데모 숨김(org_visible)을 건다. 개별 줄은 내보내지 않고 숫자만 낸다.\n\ncreate view fcd.v_current_settings with (security_invoker = true) as\n  select distinct on (key) key, value, note, created_at, created_by\n  from fcd.settings\n  order by key, created_at desc, id desc;\n\ncreate view fcd.v_current_duty_rates with (security_invoker = true) as\n  select distinct on (category) category, name_ko, rate_bp, note, created_at\n  from fcd.duty_rates\n  order by category, created_at desc, id desc;\n\n-- 현재 판 = 뒤를 잇는 판이 없는 요금표\ncreate view fcd.v_rate_cards_current with (security_invoker = true) as\n  select r.* from fcd.rate_cards r\n  where not exists (select 1 from fcd.rate_cards n where n.supersedes_id = r.id);\n\ncreate view fcd.v_bids_current with (security_invoker = true) as\n  select b.* from fcd.bids b\n  where not exists (select 1 from fcd.bids n where n.supersedes_id = b.id);\n\ncreate view fcd.v_invoices_current with (security_invoker = true) as\n  select i.* from fcd.invoices i\n  where not exists (select 1 from fcd.invoices n where n.supersedes_id = i.id);\n\n-- 견적 요청의 화면 상태\n--   응찰 대기 · 응찰 중 · 마감 임박(24시간 안) · 비교 가능(마감 뒤, 응찰 있음) · 선택 완료 · 만료(마감 뒤 응찰 없음 / 비교 기한 7일 넘김) · 취소\ncreate view fcd.v_quote_requests with (security_invoker = true) as\n  select q.*,\n    coalesce(bc.n, 0) as bid_count,\n    bc.min_total,\n    case\n      when q.status = 'cancelled' then 'cancelled'\n      when q.status = 'selected' then 'selected'\n      when q.bid_deadline > now() and coalesce(bc.n, 0) = 0 and q.bid_deadline - now() > interval '24 hours' then 'waiting'\n      when q.bid_deadline > now() and q.bid_deadline - now() <= interval '24 hours' then 'closing_soon'\n      when q.bid_deadline > now() then 'bidding'\n      when coalesce(bc.n, 0) > 0 and now() - q.bid_deadline <= interval '7 days' then 'comparable'\n      else 'expired'\n    end as display_status\n  from fcd.quote_requests q\n  left join lateral (\n    select count(*)::int as n, min(b.total)::bigint as min_total\n    from fcd.v_bids_current b where b.request_id = q.id and b.status = 'submitted'\n  ) bc on true;\n\n-- 업체 실측 점수 — 선적·청구 기록에서 계산한다. 손으로 넣는 칸이 없다.\ncreate view fcd.v_partner_metrics as\n  with done as (\n    select s.partner_org_id as org_id, s.units, s.fc_returned_units, s.delivered_at, s.eta_fc\n    from fcd.shipments s\n    where s.stage = 9 and s.delivered_at is not null\n  ),\n  inv as (\n    select i.shipment_id, i.total, i.partner_org_id\n    from fcd.invoices i\n    where not exists (select 1 from fcd.invoices n where n.supersedes_id = i.id)\n  ),\n  dev as (\n    select inv.partner_org_id as org_id,\n           (inv.total - b.total)::float8 / nullif(b.total, 0) as d\n    from inv\n    join fcd.shipments s on s.id = inv.shipment_id\n    join fcd.bookings bk on bk.id = s.booking_id\n    join fcd.bids b on b.id = bk.bid_id\n  ),\n  cert as (\n    select b.org_id, avg(b.confirmed_total::float8 / nullif(b.total, 0)) as c\n    from fcd.bids b\n    where b.created_at > now() - interval '180 days'\n    group by b.org_id\n  ),\n  rv as (\n    select partner_org_id as org_id, count(*)::int as n, avg(rating)::float8 as a\n    from fcd.reviews where published group by partner_org_id\n  )\n  select o.id as org_id,\n    (select count(*) from done where done.org_id = o.id)::int as shipments_done,\n    (select avg(case when (d.delivered_at at time zone 'Asia/Seoul')::date <= d.eta_fc then 1.0 else 0.0 end)\n       from done d where d.org_id = o.id)::float8 as on_time_rate,\n    (select sum(d.fc_returned_units)::float8 / nullif(sum(d.units), 0)\n       from done d where d.org_id = o.id and d.delivered_at > now() - interval '30 days') as return_rate_30d,\n    (select count(*) from done d where d.org_id = o.id and d.delivered_at > now() - interval '30 days')::int as done_30d,\n    (select avg(abs(dev.d)) from dev where dev.org_id = o.id)::float8 as avg_deviation,\n    (select avg(dev.d) from dev where dev.org_id = o.id)::float8 as avg_signed_deviation,\n    (select count(*) from dev where dev.org_id = o.id)::int as invoiced_count,\n    (select c from cert where cert.org_id = o.id)::float8 as price_certainty,\n    coalesce((select n from rv where rv.org_id = o.id), 0) as reviews_count,\n    (select a from rv where rv.org_id = o.id) as avg_rating\n  from fcd.orgs o\n  where o.kind = 'partner' and fcd.org_visible(o.id);\n\n-- 공개 첫 화면의 살아 있는 숫자\ncreate view fcd.v_market_counts as\n  select\n    (select count(*) from fcd.rate_cards r\n      where r.created_at >= (date_trunc('day', now() at time zone 'Asia/Seoul') at time zone 'Asia/Seoul')\n        and fcd.partner_priced(r.org_id))::int as cards_today,\n    (select count(*) from fcd.quote_requests q\n      where q.created_at >= now() - interval '7 days' and fcd.org_visible(q.org_id))::int as requests_week,\n    (select count(*) from fcd.orgs o where fcd.partner_listed(o.id))::int as partners_listed,\n    (select count(*) from fcd.orgs o\n      where o.kind = 'partner' and o.status = 'official' and fcd.org_visible(o.id))::int as partners_official,\n    (select count(*) from fcd.shipments s\n      where s.stage = 9 and s.delivered_at > now() - interval '30 days' and fcd.org_visible(s.shipper_org_id))::int as delivered_30d,\n    -- 안쪽 보기(v_rate_cards_current)는 security_invoker 라 부르는 사람의 RLS 를 받는다 — 원 표를 직접 센다\n    (select count(*) from fcd.rate_cards r\n      where not exists (select 1 from fcd.rate_cards n where n.supersedes_id = r.id)\n        and r.status = 'active' and r.valid_to >= (now() at time zone 'Asia/Seoul')::date\n        and fcd.partner_priced(r.org_id))::int as cards_active;\n\ngrant select on fcd.v_current_settings, fcd.v_current_duty_rates, fcd.v_rate_cards_current,\n  fcd.v_partner_metrics, fcd.v_market_counts to fcd_public, fcd_user;\ngrant select on fcd.v_bids_current, fcd.v_invoices_current, fcd.v_quote_requests to fcd_user;\n" },
  { name: "0005_lockdown.sql", sql: "-- FC도착 0005 — 잠금\n-- Supabase 의 기본 ACL(전역·스키마)이 어떤 모양이든, fcd 스키마의 표·보기·함수에서\n-- anon·authenticated·service_role·PUBLIC 의 권한을 걷는다.\n-- 마이그레이션 실행기가 매번 끝에 fcd.lockdown() 을 다시 부른다 — 새 표가 생겨도 새지 않는다.\n\ncreate or replace function fcd.lockdown() returns void\nlanguage plpgsql as $$\ndeclare r text; t record;\nbegin\n  execute 'revoke all on all tables in schema fcd from public';\n  execute 'revoke all on all sequences in schema fcd from public';\n  foreach r in array array['anon', 'authenticated', 'service_role'] loop\n    if exists (select 1 from pg_roles where rolname = r) then\n      execute format('revoke all on all tables in schema fcd from %I', r);\n      execute format('revoke all on all sequences in schema fcd from %I', r);\n      execute format('revoke all on all functions in schema fcd from %I', r);\n      execute format('revoke all on schema fcd from %I', r);\n    end if;\n  end loop;\n  -- 새로 생긴 표에 RLS 가 빠졌으면 켠다(정책이 없으면 아무도 못 본다 — 안전한 쪽)\n  for t in select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace\n           where n.nspname = 'fcd' and c.relkind in ('r', 'p') and not c.relrowsecurity loop\n    execute format('alter table fcd.%I enable row level security', t.relname);\n  end loop;\nend $$;\n\nrevoke all on function fcd.lockdown() from public;\nselect fcd.lockdown();\n" },
  { name: "0006_invoice_checks.sql", sql: "-- FC도착 0006 — 청구서 점검 보관 (v2 check)\n--\n-- 공개 /check 는 로그인 없이 결과만 보여 주고 저장하지 않는다. 로그인한 화주가 「이 결과 보관」을 누르면 여기에 한 줄.\n-- 규칙\n--   · 본인만 읽는다(같은 조직 동료도 못 본다 — 받은 청구서는 개인이 올린 자료).\n--   · 고치지 않는다: UPDATE·DELETE 권한이 없다. 다시 점검해 보관하면 새 판(supersedes_id = 이전 판)이 쌓인다.\n--   · 조직(화주)에 매달려 조직을 지우면 함께 사라진다(데모 걷어내기 = is_demo 조직 삭제로 끝난다).\n\ncreate table fcd.invoice_checks (\n  id uuid primary key default gen_random_uuid(),\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  user_id uuid not null references fcd.profiles (id) on delete cascade,\n  version integer not null default 1 check (version >= 1),\n  supersedes_id uuid references fcd.invoice_checks (id) on delete cascade,\n  title text not null check (char_length(title) between 1 and 80),\n  origin_hub text not null references fcd.hubs (code),\n  port text not null references fcd.ports (code),\n  mode text references fcd.modes (code),\n  cargo jsonb not null,\n  lines jsonb not null,\n  result jsonb not null,\n  invoice_total bigint not null,\n  market_median bigint,\n  -- (빠진 구간 예상을 더한 합계 − 중간값) / 중간값, bp. 표본이 모자라면 null\n  over_median_bp integer,\n  high_count smallint not null default 0 check (high_count between 0 and 9),\n  missing_count smallint not null default 0 check (missing_count between 0 and 9),\n  created_at timestamptz not null default now()\n);\ncreate index invoice_checks_user_idx on fcd.invoice_checks (user_id, created_at desc);\ncreate unique index invoice_checks_one_successor on fcd.invoice_checks (supersedes_id) where supersedes_id is not null;\n\n-- 새 판을 쌓을 때 이전 판이 본인 것인지 — 정책 안에서 같은 표를 다시 읽지 않게 security definer 로\ncreate or replace function fcd.owns_invoice_check(c uuid) returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select exists (select 1 from fcd.invoice_checks where id = c and user_id = fcd.uid())\n$$;\nrevoke all on function fcd.owns_invoice_check(uuid) from public;\ngrant execute on function fcd.owns_invoice_check(uuid) to fcd_user;\n\nalter table fcd.invoice_checks enable row level security;\ngrant select, insert on fcd.invoice_checks to fcd_user;\n\ncreate policy invoice_checks_read on fcd.invoice_checks for select to fcd_user\n  using (user_id = fcd.uid() and fcd.org_visible(org_id));\n\ncreate policy invoice_checks_insert on fcd.invoice_checks for insert to fcd_user with check (\n  user_id = fcd.uid()\n  and fcd.is_member(org_id)\n  and fcd.org_kind(org_id) = 'shipper'\n  and (supersedes_id is null or fcd.owns_invoice_check(supersedes_id))\n);\n\ncreate view fcd.v_invoice_checks_current with (security_invoker = true) as\n  select c.* from fcd.invoice_checks c\n  where not exists (select 1 from fcd.invoice_checks n where n.supersedes_id = c.id);\n\ngrant select on fcd.v_invoice_checks_current to fcd_user;\n" },
  { name: "0007_reviews_v2.sql", sql: "-- FC도착 0007 — 점수·후기 정직하게 (v2 trust)\n--\n-- ① 후기가 어떤 끝으로 끝난 선적에 대한 것인가(outcome)\n--    선적 상태값은 표준 9단계(stage 1~9) · FC 회송 수량(fc_returned_units) · 예외(exceptions.kind) 뿐이다.\n--    「분실」 상태값은 없다 — 그래서 끝을 이 값들에서 읽는다:\n--      delivered    FC 입고 완료(9단계), 회송 없음\n--      fc_returned  FC 입고 완료(9단계), 회송 수량 있음\n--      fc_rejected  9단계 전인데 「FC 입고 반려」 예외가 열린 적 있음\n--      lost         9단계 전, FC 도착 예정일 + 설정 review_lost_after_days 일이 지남(분실·미도착)\n--    화주가 고르는 값이 아니다. 넣을 때 정책이 선적 기록에서 다시 계산해 같은지 본다.\n--    이 파일 전 후기(outcome 이 빈 줄)는 모두 9단계 뒤에 남은 것 — 읽을 때 선적 기록으로 채운다(고쳐 쓰지 않는다).\n--\n-- ② 업체 공개 답변(review_replies) — 고치지 않고 새 판(supersedes_id)으로 쌓는다. UPDATE·DELETE 권한 없음.\n--\n-- ③ 점수 표본·청구 편차 분포를 읽는 함수(partner_trust_facts) — 숫자만 낸다(선적·화주를 가리키는 값 없음).\n--\n-- 지우거나 덮는 문장이 없다(열 추가·새 표·새 함수·새 정책만).\n\nalter table fcd.reviews add column if not exists outcome text\n  check (outcome in ('delivered', 'fc_returned', 'fc_rejected', 'lost'));\n\n-- 설정 값 읽기(숫자). 운영 DB 에 글자로 감싸 저장된 jsonb(\"14\")도 읽는다.\ncreate or replace function fcd.setting_num(k text) returns numeric\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select nullif(value #>> '{}', '')::numeric from fcd.v_current_settings where key = k\n$$;\n\n-- 선적의 끝 — 순수 판정(표를 읽지 않는다)\ncreate or replace function fcd.outcome_of(p_stage smallint, p_returned integer, p_rejected boolean, p_eta date, p_lost_days numeric, p_today date)\nreturns text language sql immutable as $$\n  select case\n    when p_stage = 9 and coalesce(p_returned, 0) > 0 then 'fc_returned'\n    when p_stage = 9 then 'delivered'\n    when p_rejected then 'fc_rejected'\n    when p_eta is not null and p_lost_days is not null and p_eta + p_lost_days::int < p_today then 'lost'\n    else null\n  end\n$$;\n\n-- 선적 하나의 끝(평가할 수 있으면 값, 아직이면 null)\ncreate or replace function fcd.shipment_outcome(s uuid) returns text\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select fcd.outcome_of(\n    x.stage, x.fc_returned_units,\n    exists (select 1 from fcd.exceptions e where e.shipment_id = x.id and e.kind = 'fc_rejected'),\n    x.eta_fc, fcd.setting_num('review_lost_after_days'), (now() at time zone 'Asia/Seoul')::date)\n  from fcd.shipments x where x.id = s\n$$;\n\n-- 후기의 끝 — 적어 둔 값이 있으면 그것, 없으면(이전 후기) 선적 기록에서\ncreate or replace function fcd.review_outcome(r uuid) returns text\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select coalesce(v.outcome, fcd.shipment_outcome(v.shipment_id)) from fcd.reviews v where v.id = r\n$$;\n\n-- 후기를 볼 수 있는가(reviews 읽기 정책과 같은 뜻)\ncreate or replace function fcd.review_visible(r uuid) returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select exists (\n    select 1 from fcd.reviews v\n    where v.id = r and fcd.org_visible(v.shipper_org_id) and fcd.org_visible(v.partner_org_id)\n      and ((v.published and fcd.partner_listed(v.partner_org_id))\n           or fcd.is_member(v.shipper_org_id) or fcd.is_member(v.partner_org_id) or fcd.is_platform())\n  )\n$$;\n\ncreate or replace function fcd.review_partner(r uuid) returns uuid\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select partner_org_id from fcd.reviews where id = r\n$$;\n\n-- 새 후기는 끝(outcome)을 반드시 적고, 그 값이 선적 기록과 같아야 한다(평가할 수 없는 선적이면 null 이라 막힌다).\n-- 기존 허용 정책(reviews_insert)에 더해 걸리는 제한 정책이다.\ncreate policy reviews_insert_outcome on fcd.reviews as restrictive for insert to fcd_user\n  with check (outcome is not null and outcome = fcd.shipment_outcome(shipment_id));\n\n-- 업체 공개 답변 ------------------------------------------------------------\ncreate table fcd.review_replies (\n  id uuid primary key default gen_random_uuid(),\n  review_id uuid not null references fcd.reviews (id) on delete cascade,\n  partner_org_id uuid not null references fcd.orgs (id) on delete cascade,\n  version integer not null default 1 check (version >= 1),\n  supersedes_id uuid references fcd.review_replies (id) on delete cascade,\n  body text not null check (char_length(body) between 5 and 600),\n  created_by uuid,\n  created_at timestamptz not null default now(),\n  check ((version = 1) = (supersedes_id is null))\n);\ncreate index review_replies_review_idx on fcd.review_replies (review_id);\n-- 한 후기에 첫 판은 하나, 한 판을 잇는 판도 하나(갈래가 생기지 않는다)\ncreate unique index review_replies_first on fcd.review_replies (review_id) where supersedes_id is null;\ncreate unique index review_replies_one_successor on fcd.review_replies (supersedes_id) where supersedes_id is not null;\n\n-- 새 판을 이을 때 같은 후기·같은 업체의 바로 앞 판인지\ncreate or replace function fcd.reply_chain_ok(p_supersedes uuid, p_review uuid, p_partner uuid, p_version integer) returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select case when p_supersedes is null then p_version = 1\n    else exists (select 1 from fcd.review_replies p\n                 where p.id = p_supersedes and p.review_id = p_review and p.partner_org_id = p_partner and p.version + 1 = p_version)\n  end\n$$;\n\nalter table fcd.review_replies enable row level security;\ngrant select on fcd.review_replies to fcd_public, fcd_user;\ngrant insert on fcd.review_replies to fcd_user;\ncreate policy replies_read on fcd.review_replies for select to fcd_public, fcd_user using (fcd.review_visible(review_id));\ncreate policy replies_insert on fcd.review_replies for insert to fcd_user with check (\n  fcd.is_member(partner_org_id)\n  and partner_org_id = fcd.review_partner(review_id)\n  and fcd.review_visible(review_id)\n  and created_by = fcd.uid()\n  and fcd.reply_chain_ok(supersedes_id, review_id, partner_org_id, version)\n);\n\ncreate view fcd.v_review_replies_current with (security_invoker = true) as\n  select r.* from fcd.review_replies r\n  where not exists (select 1 from fcd.review_replies n where n.supersedes_id = r.id);\ngrant select on fcd.v_review_replies_current to fcd_public, fcd_user;\n\n-- 점수 표본·편차 분포 ---------------------------------------------------------\n-- p_days 일 안에 끝난 선적(outcome 이 있는 것) 수와 끝별 수, 그리고 청구 편차 목록(작은 값부터).\n-- 편차 정의는 v_partner_metrics 와 같다: (현재 판 청구 합계 − 응찰 합계) / 응찰 합계.\ncreate or replace function fcd.partner_trust_facts(p_orgs uuid[], p_days integer)\nreturns table (org_id uuid, sample_n integer, delivered_n integer, returned_n integer, rejected_n integer, lost_n integer, deviations float8[])\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  with o as (\n    select id from fcd.orgs where id = any(p_orgs) and kind = 'partner' and fcd.org_visible(id)\n  ),\n  k as (select fcd.setting_num('review_lost_after_days') as lost_days, (now() at time zone 'Asia/Seoul')::date as today),\n  sh as (\n    select s.partner_org_id as org_id,\n           fcd.outcome_of(s.stage, s.fc_returned_units, rj.first_at is not null, s.eta_fc, k.lost_days, k.today) as outcome,\n           case when s.stage = 9 then s.delivered_at\n                when rj.first_at is not null then rj.first_at\n                else ((s.eta_fc + k.lost_days::int)::timestamp at time zone 'Asia/Seoul') end as ended_at\n    from fcd.shipments s\n    cross join k\n    left join lateral (select min(e.opened_at) as first_at from fcd.exceptions e where e.shipment_id = s.id and e.kind = 'fc_rejected') rj on true\n    where s.partner_org_id in (select id from o)\n  ),\n  win as (select * from sh where outcome is not null and ended_at > now() - make_interval(days => p_days)),\n  dev as (\n    select i.partner_org_id as org_id, (i.total - b.total)::float8 / nullif(b.total, 0) as d\n    from fcd.invoices i\n    join fcd.shipments s on s.id = i.shipment_id\n    join fcd.bookings bk on bk.id = s.booking_id\n    join fcd.bids b on b.id = bk.bid_id\n    where i.partner_org_id in (select id from o)\n      and not exists (select 1 from fcd.invoices n where n.supersedes_id = i.id)\n  )\n  select o.id,\n    (select count(*) from win where win.org_id = o.id)::int,\n    (select count(*) from win where win.org_id = o.id and outcome = 'delivered')::int,\n    (select count(*) from win where win.org_id = o.id and outcome = 'fc_returned')::int,\n    (select count(*) from win where win.org_id = o.id and outcome = 'fc_rejected')::int,\n    (select count(*) from win where win.org_id = o.id and outcome = 'lost')::int,\n    coalesce((select array_agg(dev.d order by dev.d) from dev where dev.org_id = o.id and dev.d is not null), '{}'::float8[])\n  from o\n$$;\n\ndo $$\ndeclare f text;\nbegin\n  foreach f in array array[\n    'setting_num(text)', 'shipment_outcome(uuid)', 'review_outcome(uuid)', 'review_visible(uuid)', 'review_partner(uuid)',\n    'reply_chain_ok(uuid, uuid, uuid, integer)', 'partner_trust_facts(uuid[], integer)',\n    'outcome_of(smallint, integer, boolean, date, numeric, date)'\n  ] loop\n    execute format('revoke all on function fcd.%s from public', f);\n    execute format('grant execute on function fcd.%s to fcd_public, fcd_user', f);\n  end loop;\nend $$;\n" },
  { name: "0008_assure.sql", sql: "-- FC도착 0008 — 확정가·보장 자리(v2 assure)\n--\n-- 계약을 떠안거나 돈을 받는 기능은 자리만 만든다. 켜는 값은 fcd.settings 의 v2.* 스위치(기본 꺼짐).\n-- 켜도 실제 계약·결제는 없다 — 확정가는 국제물류주선업 등록, 보장은 보험사, 후불은 금융사 제휴가 전제다.\n--\n--   · assure_interests  — 「관심 등록」(확정가 firm · 회송 보장 coverage · 물류비 후불 deferred · 공동 혼적 consolidation).\n--                          본인 것만 보고, 운영자는 모두 본다. 고치거나 지울 권한이 없다.\n--   · firm_price_quotes — 시범 확정가 견적 기록. 거래 기록이라 UPDATE 권한이 없고, 다시 내면 새 판(supersedes_id).\n\ncreate table fcd.assure_interests (\n  id uuid primary key default gen_random_uuid(),\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  user_id uuid not null references fcd.profiles (id) on delete cascade,\n  kind text not null check (kind in ('firm', 'coverage', 'deferred', 'consolidation')),\n  source text not null check (source in ('compare', 'request', 'other')),\n  detail jsonb,\n  note text check (note is null or length(note) <= 300),\n  created_at timestamptz not null default now()\n);\ncreate unique index assure_interests_one on fcd.assure_interests (user_id, kind);\ncreate index assure_interests_org_idx on fcd.assure_interests (org_id, created_at desc);\n\ncreate table fcd.firm_price_quotes (\n  id uuid primary key default gen_random_uuid(),\n  quote_no text not null,\n  version integer not null default 1 check (version >= 1),\n  supersedes_id uuid references fcd.firm_price_quotes (id) on delete cascade,\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  created_by uuid not null references fcd.profiles (id) on delete cascade,\n  source text not null check (source in ('compare', 'request')),\n  request_id uuid references fcd.quote_requests (id) on delete cascade,\n  lane jsonb not null,\n  sample_n integer not null check (sample_n >= 1),\n  base_total bigint not null check (base_total >= 0),\n  premium bigint not null check (premium >= 0),\n  firm_price bigint not null check (firm_price >= base_total),\n  confidence_bp integer not null check (confidence_bp between 5000 and 9999),\n  stats jsonb not null,\n  rates jsonb not null,\n  pilot boolean not null default true,\n  valid_until date not null,\n  created_at timestamptz not null default now(),\n  unique (quote_no, version)\n);\ncreate index firm_price_quotes_org_idx on fcd.firm_price_quotes (org_id, created_at desc);\ncreate unique index firm_price_quotes_one_successor on fcd.firm_price_quotes (supersedes_id) where supersedes_id is not null;\n\nalter table fcd.assure_interests enable row level security;\nalter table fcd.firm_price_quotes enable row level security;\n\n-- 관심 등록 — 본인 것만, 운영자는 모두 --------------------------------------------\ngrant select, insert on fcd.assure_interests to fcd_user;\ncreate policy ai_read on fcd.assure_interests for select to fcd_user using (\n  fcd.org_visible(org_id) and (user_id = fcd.uid() or fcd.is_platform())\n);\ncreate policy ai_insert on fcd.assure_interests for insert to fcd_user with check (\n  user_id = fcd.uid() and fcd.is_member(org_id) and fcd.org_kind(org_id) = 'shipper'\n);\n\n-- 확정가 견적 — 수정 권한 없음, 새 판만 --------------------------------------------\ngrant select, insert on fcd.firm_price_quotes to fcd_user;\ncreate policy fpq_read on fcd.firm_price_quotes for select to fcd_user using (\n  fcd.org_visible(org_id) and (fcd.is_member(org_id) or fcd.is_platform())\n);\ncreate policy fpq_insert on fcd.firm_price_quotes for insert to fcd_user with check (\n  created_by = fcd.uid() and fcd.is_member(org_id) and fcd.org_kind(org_id) = 'shipper'\n  and (request_id is null or exists (select 1 from fcd.quote_requests q where q.id = request_id and q.org_id = firm_price_quotes.org_id))\n  and (firm_price_quotes.supersedes_id is null or exists (select 1 from fcd.firm_price_quotes p where p.id = firm_price_quotes.supersedes_id and p.org_id = firm_price_quotes.org_id))\n);\n" },
  { name: "0009_workspace.sql", sql: "-- FC도착 0009 — 셀러 공간(workspace)\n--   ① 서류함 칸(documents.shelf) — 인보이스·패킹리스트·쿠팡 바코드 PDF·B/L·기타\n--   ② 청구 승인/이의(invoice_decisions) — 덧붙이기만. 결정을 바꾸면 새 판(supersedes_id)\n--   ③ 거래처 초대(partner_invites) — 토큰은 해시만 저장, 만료, 한 번 쓰면 끝\n--   ④ 거래처 연결(shipper_partners) — 초대 링크로 들어온 물류사를 그 화주의 거래처로\n--\n-- 이 파일은 자료를 지우거나 덮지 않는다. 기존 표의 제약도 풀지 않는다\n-- (documents.kind 의 check 를 넓히려면 DROP CONSTRAINT 가 필요해, 대신 칸을 하나 덧붙였다).\n\n-- ① 서류함 칸 ------------------------------------------------------------------\n-- 비어 있으면 kind 로 가른다(commercial_invoice → invoice, packing_list → packing_list, bl → bl, 나머지 → other).\nalter table fcd.documents add column if not exists shelf text\n  check (shelf in ('invoice', 'packing_list', 'coupang_barcode', 'bl', 'other'));\n\ncreate or replace function fcd.doc_shelf(p_kind text, p_shelf text) returns text\nlanguage sql immutable as $$\n  select coalesce(p_shelf, case p_kind\n    when 'commercial_invoice' then 'invoice'\n    when 'packing_list' then 'packing_list'\n    when 'bl' then 'bl'\n    else 'other' end)\n$$;\nrevoke all on function fcd.doc_shelf(text, text) from public;\ngrant execute on function fcd.doc_shelf(text, text) to fcd_public, fcd_user;\n\n-- 서류 한 장 = 한 줄. 서류함 칸을 계산해 붙인다. 읽기 권한은 documents 의 RLS 그대로(security_invoker).\ncreate view fcd.v_documents with (security_invoker = true) as\n  select d.*, fcd.doc_shelf(d.kind, d.shelf) as box from fcd.documents d;\ngrant select on fcd.v_documents to fcd_user;\n\n-- ② 청구 승인/이의 ---------------------------------------------------------------\n-- 화주가 물류사 청구서(현재 판)에 「승인」 또는 「이의(사유)」를 남긴다.\n-- 고치지 않는다: 결정을 바꾸면 supersedes_id 로 새 판. 청구서가 새 판으로 정정되면 결정은 그 새 청구서에 새로 남긴다.\ncreate table fcd.invoice_decisions (\n  id uuid primary key default gen_random_uuid(),\n  invoice_id uuid not null references fcd.invoices (id) on delete cascade,\n  shipment_id uuid not null references fcd.shipments (id) on delete cascade,\n  shipper_org_id uuid not null references fcd.orgs (id) on delete cascade,\n  decision text not null check (decision in ('approved', 'disputed')),\n  reason text check (reason is null or length(reason) <= 1000),\n  -- 결정할 때 본 금액(견적 대비 차이의 근거) — 스냅숏\n  quote_total bigint not null check (quote_total >= 0),\n  invoice_total bigint not null check (invoice_total >= 0),\n  supersedes_id uuid references fcd.invoice_decisions (id) on delete cascade,\n  created_by uuid,\n  created_at timestamptz not null default now(),\n  check (decision = 'approved' or length(btrim(coalesce(reason, ''))) >= 5)\n);\ncreate index invoice_decisions_inv_idx on fcd.invoice_decisions (invoice_id, created_at desc);\ncreate index invoice_decisions_ship_idx on fcd.invoice_decisions (shipment_id);\ncreate unique index invoice_decisions_one_successor on fcd.invoice_decisions (supersedes_id) where supersedes_id is not null;\ncreate unique index invoice_decisions_one_root on fcd.invoice_decisions (invoice_id) where supersedes_id is null;\n\ncreate view fcd.v_invoice_decisions_current with (security_invoker = true) as\n  select d.* from fcd.invoice_decisions d\n  where not exists (select 1 from fcd.invoice_decisions n where n.supersedes_id = d.id);\ngrant select on fcd.v_invoice_decisions_current to fcd_user;\n\n-- 결정을 남겨도 되는 청구서인가: 그 선적의 현재 판 청구서이고, 새 판이면 같은 청구서의 현재 결정을 잇는다.\ncreate or replace function fcd.invoice_decision_ok(p_invoice uuid, p_shipment uuid, p_shipper uuid, p_super uuid) returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select exists (\n      select 1 from fcd.invoices i join fcd.shipments s on s.id = i.shipment_id\n      where i.id = p_invoice and i.shipment_id = p_shipment and s.shipper_org_id = p_shipper\n        and not exists (select 1 from fcd.invoices n where n.supersedes_id = i.id)\n    )\n    and (\n      (p_super is null and not exists (select 1 from fcd.invoice_decisions d where d.invoice_id = p_invoice))\n      or exists (\n        select 1 from fcd.invoice_decisions d\n        where d.id = p_super and d.invoice_id = p_invoice\n          and not exists (select 1 from fcd.invoice_decisions n where n.supersedes_id = d.id)\n      )\n    )\n$$;\nrevoke all on function fcd.invoice_decision_ok(uuid, uuid, uuid, uuid) from public;\ngrant execute on function fcd.invoice_decision_ok(uuid, uuid, uuid, uuid) to fcd_user;\n\nalter table fcd.invoice_decisions enable row level security;\ngrant select, insert on fcd.invoice_decisions to fcd_user; -- UPDATE·DELETE 없음\ncreate policy inv_dec_read on fcd.invoice_decisions for select to fcd_user using (\n  fcd.org_visible(shipper_org_id) and fcd.can_see_shipment(shipment_id)\n);\ncreate policy inv_dec_insert on fcd.invoice_decisions for insert to fcd_user with check (\n  fcd.is_member(shipper_org_id) and fcd.org_kind(shipper_org_id) = 'shipper'\n  and created_by = fcd.uid()\n  and fcd.invoice_decision_ok(invoice_id, shipment_id, shipper_org_id, supersedes_id)\n);\n\n-- ③ 거래처 초대 -----------------------------------------------------------------\n-- 링크의 토큰 자체는 저장하지 않는다(sha-256 16진 64자만). 링크는 만들 때 한 번만 화면에 보인다.\ncreate table fcd.partner_invites (\n  id uuid primary key default gen_random_uuid(),\n  shipper_org_id uuid not null references fcd.orgs (id) on delete cascade,\n  token_hash text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),\n  partner_name text not null check (length(btrim(partner_name)) between 1 and 80),\n  contact_email text check (contact_email is null or length(contact_email) <= 120),\n  note text check (note is null or length(note) <= 400),\n  expires_at timestamptz not null,\n  revoked_at timestamptz,\n  created_by uuid,\n  created_at timestamptz not null default now(),\n  check (expires_at > created_at)\n);\ncreate index partner_invites_org_idx on fcd.partner_invites (shipper_org_id, created_at desc);\n\n-- ④ 거래처 연결 -----------------------------------------------------------------\ncreate table fcd.shipper_partners (\n  shipper_org_id uuid not null references fcd.orgs (id) on delete cascade,\n  partner_org_id uuid not null references fcd.orgs (id) on delete cascade,\n  invite_id uuid references fcd.partner_invites (id) on delete set null,\n  created_by uuid,\n  created_at timestamptz not null default now(),\n  primary key (shipper_org_id, partner_org_id),\n  check (shipper_org_id <> partner_org_id)\n);\ncreate unique index shipper_partners_one_use on fcd.shipper_partners (invite_id) where invite_id is not null;\ncreate index shipper_partners_partner_idx on fcd.shipper_partners (partner_org_id);\n\nalter table fcd.partner_invites enable row level security;\nalter table fcd.shipper_partners enable row level security;\n\n-- 초대: 만든 화주 조직 사람만 본다. 해시 칸은 읽기 권한에서 뺀다(칸 단위 권한).\ngrant select (id, shipper_org_id, partner_name, contact_email, note, expires_at, revoked_at, created_by, created_at) on fcd.partner_invites to fcd_user;\ngrant insert (shipper_org_id, token_hash, partner_name, contact_email, note, expires_at, created_by) on fcd.partner_invites to fcd_user;\ngrant update (revoked_at) on fcd.partner_invites to fcd_user; -- 거두기만\ncreate policy invites_read on fcd.partner_invites for select to fcd_user using (\n  fcd.org_visible(shipper_org_id) and (fcd.is_member(shipper_org_id) or fcd.is_platform())\n);\ncreate policy invites_insert on fcd.partner_invites for insert to fcd_user with check (\n  fcd.is_member(shipper_org_id) and fcd.org_kind(shipper_org_id) = 'shipper' and created_by = fcd.uid()\n);\ncreate policy invites_revoke on fcd.partner_invites for update to fcd_user\n  using (fcd.is_member(shipper_org_id))\n  with check (fcd.is_member(shipper_org_id) and revoked_at is not null);\n\n-- 연결: 두 조직 사람과 운영자가 본다. 넣기는 아래 함수로만(초대 확인을 건너뛰지 못하게 INSERT 권한 없음).\ngrant select on fcd.shipper_partners to fcd_user;\ncreate policy shipper_partners_read on fcd.shipper_partners for select to fcd_user using (\n  fcd.org_visible(shipper_org_id) and fcd.org_visible(partner_org_id)\n  and (fcd.is_member(shipper_org_id) or fcd.is_member(partner_org_id) or fcd.is_platform())\n);\n\n-- 초대 상태 보기 — 링크를 연 사람(로그인 전 포함)에게 필요한 것만: 상태·화주 이름·받는 곳 이름·만료.\ncreate or replace function fcd.invite_lookup(p_hash text)\nreturns table (status text, shipper_name text, partner_name text, expires_at timestamptz)\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select\n    case\n      when i.revoked_at is not null then 'revoked'\n      when exists (select 1 from fcd.shipper_partners sp where sp.invite_id = i.id) then 'used'\n      when i.expires_at <= now() then 'expired'\n      else 'open'\n    end,\n    o.name, i.partner_name, i.expires_at\n  from fcd.partner_invites i join fcd.orgs o on o.id = i.shipper_org_id\n  where i.token_hash = p_hash and fcd.org_visible(i.shipper_org_id)\n$$;\nrevoke all on function fcd.invite_lookup(text) from public;\ngrant execute on function fcd.invite_lookup(text) to fcd_public, fcd_user;\n\n-- 초대 받기 — 물류사 조직 관리자만. 열린 초대면 연결을 넣고 'ok'. 아니면 까닭을 돌려준다.\ncreate or replace function fcd.accept_partner_invite(p_hash text, p_partner uuid) returns text\nlanguage plpgsql security definer set search_path = fcd, pg_temp as $$\ndeclare\n  inv record;\n  n integer;\nbegin\n  if fcd.uid() is null or not fcd.is_org_admin(p_partner) or coalesce(fcd.org_kind(p_partner), '') <> 'partner' then\n    return 'not_partner_admin';\n  end if;\n  select i.id, i.shipper_org_id, i.expires_at, i.revoked_at into inv\n    from fcd.partner_invites i where i.token_hash = p_hash for update;\n  if not found or not fcd.org_visible(inv.shipper_org_id) then return 'not_found'; end if;\n  if inv.revoked_at is not null then return 'revoked'; end if;\n  if exists (select 1 from fcd.shipper_partners sp where sp.invite_id = inv.id) then return 'used'; end if;\n  if inv.expires_at <= now() then return 'expired'; end if;\n  insert into fcd.shipper_partners (shipper_org_id, partner_org_id, invite_id, created_by)\n    values (inv.shipper_org_id, p_partner, inv.id, fcd.uid())\n    on conflict (shipper_org_id, partner_org_id) do nothing;\n  get diagnostics n = row_count;\n  if n = 0 then return 'already'; end if;\n  return 'ok';\nend $$;\nrevoke all on function fcd.accept_partner_invite(text, uuid) from public;\ngrant execute on function fcd.accept_partner_invite(text, uuid) to fcd_user;\n" },
  { name: "0010_events.sql", sql: "-- FC도착 0010 — 이벤트 기록(v2 metrics)\n--\n-- 견적 요청 → 응찰 → 선택 → 예약 → 선적(출항) → FC 입고 → 청구 → 회송 · 평가 · 가입을 한 줄씩 쌓는다.\n-- 쌓기만 한다: 어떤 역할에도 UPDATE·DELETE 권한이 없다. 조직을 지우면 CASCADE 로 함께 사라진다(데모 걷어내기).\n-- 금액은 여기에 복사하지 않는다 — 지표는 대상(응찰·청구·선적)을 따라가 원래 기록에서 읽는다.\n\ncreate table fcd.events (\n  id uuid primary key default gen_random_uuid(),\n  -- 행동한 쪽 조직\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  -- 이 일이 걸린 셀러(화주) 조직 — 월간 활성 셀러·재선적률의 기준\n  seller_org_id uuid references fcd.orgs (id) on delete cascade,\n  actor_id uuid,\n  kind text not null check (kind in (\n    'signed_up', 'quote_requested', 'request_cancelled', 'bid_submitted', 'bid_selected', 'booked',\n    'shipped', 'fc_inbound', 'invoiced', 'returned', 'reviewed'\n  )),\n  target_kind text check (target_kind in ('org', 'quote_request', 'shipment')),\n  target_id uuid,\n  detail jsonb,\n  occurred_at timestamptz not null default now(),\n  created_at timestamptz not null default now()\n);\ncreate index events_kind_idx on fcd.events (kind, occurred_at desc);\ncreate index events_seller_idx on fcd.events (seller_org_id, occurred_at desc);\ncreate index events_org_idx on fcd.events (org_id, occurred_at desc);\ncreate index events_target_idx on fcd.events (target_id);\n\nalter table fcd.events enable row level security;\n\ngrant select, insert on fcd.events to fcd_user;\n\n-- 읽기: 운영자는 전부, 조직은 자기가 한 일만(데모 숨김을 따른다)\ncreate policy events_read on fcd.events for select to fcd_user using (\n  fcd.is_platform() or (fcd.org_visible(org_id) and fcd.is_member(org_id))\n);\n\n-- 쓰기: 로그인한 본인이, 자기 조직 이름으로만. 셀러를 적을 때는 그 셀러와 걸린 일이어야 한다.\ncreate policy events_insert on fcd.events for insert to fcd_user with check (\n  actor_id = fcd.uid()\n  and fcd.is_member(org_id)\n  and (\n    seller_org_id is null\n    or fcd.is_member(seller_org_id)\n    or fcd.has_booking_with(seller_org_id)\n    or (target_kind = 'quote_request' and exists (\n          select 1 from fcd.quote_requests q where q.id = target_id and q.org_id = seller_org_id))\n  )\n);\n" },
  { name: "0011_destinations.sql", sql: "-- FC도착 0011 — 목적지 넓히기(v2 metrics)\n--\n-- 도착지는 지금까지 쿠팡 FC(fcd.fc_centers)뿐이었다. 같은 참조표에 국내 3PL 창고·다른 쇼핑몰 물류센터를\n-- 함께 두고 kind 로 가른다 — 견적 요청·선적의 fc_code 외래키를 그대로 쓸 수 있다.\n-- 표 이름은 바꾸지 않는다(운영 자료·쿼리를 건드리지 않는다). 기존 줄은 kind 기본값 'coupang_fc' 가 된다.\n-- 줄은 참조 시드(seed/reference)가 넣는다. 예시 창고는 is_example = true 이고 이름에 「예시」가 붙는다.\n\nalter table fcd.fc_centers add column if not exists kind text not null default 'coupang_fc';\nalter table fcd.fc_centers add column if not exists is_example boolean not null default false;\nalter table fcd.fc_centers add column if not exists ord smallint not null default 0;\n\ndo $$\nbegin\n  if not exists (select 1 from pg_constraint where conname = 'fc_centers_kind_check') then\n    alter table fcd.fc_centers add constraint fc_centers_kind_check check (kind in ('coupang_fc', '3pl', 'mall_wh'));\n  end if;\nend $$;\n\n-- 목적지 보기 — 누구나 읽는다(참조표와 같은 권한)\ncreate view fcd.v_destinations with (security_invoker = true) as\n  select code, name, region, kind, is_example, km_incheon, km_pyeongtaek, ord\n  from fcd.fc_centers;\n\ngrant select on fcd.v_destinations to fcd_public, fcd_user;\n" },
  { name: "0012_v2_access_fixes.sql", sql: "-- FC도착 0012 — v2 검토에서 나온 권한 조이기(0007·0009·0010 보강)\n--\n-- 자료를 지우거나 덮지 않는다. 기존 정책은 지우지 않고, 제한(restrictive) 정책을 덧붙여 좁힌다.\n-- 함수는 같은 이름·같은 인자로 다시 만든다(create or replace) — 부르는 쪽은 그대로다.\n--\n--   ① fcd.shipment_outcome · review_outcome · review_partner — 볼 수 있는 선적·후기일 때만 값을 낸다\n--   ② fcd.partner_trust_facts — 목록에 오른(심사 중·정지가 아닌) 업체만. 본인 조직·운영자는 그대로 본다\n--   ③ 초대 거두기 — 이미 거둔 초대는 다시 고칠 수 없고, 거둔 시각은 지금 이전만\n--   ④ 이벤트 쓰기 — 대상(선적·견적 요청)을 볼 수 있어야 하고, 셀러는 그 대상의 셀러, 가입은 자기 조직만\n\n-- ① ---------------------------------------------------------------------------\n-- 보는 사람 조건 없이 선적 기록에서 끝을 읽는 속 함수. 누구에게도 실행 권한을 주지 않는다(아래 security definer 함수만 부른다).\ncreate or replace function fcd.shipment_outcome_raw(s uuid) returns text\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select fcd.outcome_of(\n    x.stage, x.fc_returned_units,\n    exists (select 1 from fcd.exceptions e where e.shipment_id = x.id and e.kind = 'fc_rejected'),\n    x.eta_fc, fcd.setting_num('review_lost_after_days'), (now() at time zone 'Asia/Seoul')::date)\n  from fcd.shipments x where x.id = s\n$$;\nrevoke all on function fcd.shipment_outcome_raw(uuid) from public;\n\ncreate or replace function fcd.shipment_outcome(s uuid) returns text\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select case when fcd.can_see_shipment(s) then fcd.shipment_outcome_raw(s) end\n$$;\n\n-- 공개 후기(0007 전 후기)도 끝을 채워야 하므로 선적 가시성이 아니라 후기 가시성으로 본다\ncreate or replace function fcd.review_outcome(r uuid) returns text\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select coalesce(v.outcome, fcd.shipment_outcome_raw(v.shipment_id))\n    from fcd.reviews v where v.id = r and fcd.review_visible(r)\n$$;\n\ncreate or replace function fcd.review_partner(r uuid) returns uuid\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select partner_org_id from fcd.reviews where id = r and fcd.review_visible(r)\n$$;\n\n-- ② ---------------------------------------------------------------------------\ncreate or replace function fcd.partner_trust_facts(p_orgs uuid[], p_days integer)\nreturns table (org_id uuid, sample_n integer, delivered_n integer, returned_n integer, rejected_n integer, lost_n integer, deviations float8[])\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  with o as (\n    select id from fcd.orgs\n     where id = any(p_orgs) and kind = 'partner' and fcd.org_visible(id)\n       and (fcd.partner_listed(id) or fcd.is_member(id) or fcd.is_platform())\n  ),\n  k as (select fcd.setting_num('review_lost_after_days') as lost_days, (now() at time zone 'Asia/Seoul')::date as today),\n  sh as (\n    select s.partner_org_id as org_id,\n           fcd.outcome_of(s.stage, s.fc_returned_units, rj.first_at is not null, s.eta_fc, k.lost_days, k.today) as outcome,\n           case when s.stage = 9 then s.delivered_at\n                when rj.first_at is not null then rj.first_at\n                else ((s.eta_fc + k.lost_days::int)::timestamp at time zone 'Asia/Seoul') end as ended_at\n    from fcd.shipments s\n    cross join k\n    left join lateral (select min(e.opened_at) as first_at from fcd.exceptions e where e.shipment_id = s.id and e.kind = 'fc_rejected') rj on true\n    where s.partner_org_id in (select id from o)\n  ),\n  win as (select * from sh where outcome is not null and ended_at > now() - make_interval(days => p_days)),\n  dev as (\n    select i.partner_org_id as org_id, (i.total - b.total)::float8 / nullif(b.total, 0) as d\n    from fcd.invoices i\n    join fcd.shipments s on s.id = i.shipment_id\n    join fcd.bookings bk on bk.id = s.booking_id\n    join fcd.bids b on b.id = bk.bid_id\n    where i.partner_org_id in (select id from o)\n      and not exists (select 1 from fcd.invoices n where n.supersedes_id = i.id)\n  )\n  select o.id,\n    (select count(*) from win where win.org_id = o.id)::int,\n    (select count(*) from win where win.org_id = o.id and outcome = 'delivered')::int,\n    (select count(*) from win where win.org_id = o.id and outcome = 'fc_returned')::int,\n    (select count(*) from win where win.org_id = o.id and outcome = 'fc_rejected')::int,\n    (select count(*) from win where win.org_id = o.id and outcome = 'lost')::int,\n    coalesce((select array_agg(dev.d order by dev.d) from dev where dev.org_id = o.id and dev.d is not null), '{}'::float8[])\n  from o\n$$;\n\n-- ③ ---------------------------------------------------------------------------\n-- 기존 invites_revoke(허용)에 더해 걸린다: 아직 거두지 않은 초대만, 거둔 시각은 지금 이전\ncreate policy invites_revoke_once on fcd.partner_invites as restrictive for update to fcd_user\n  using (revoked_at is null)\n  with check (revoked_at is not null and revoked_at <= now());\n\n-- ④ ---------------------------------------------------------------------------\ncreate or replace function fcd.event_target_ok(p_kind text, p_target_kind text, p_target uuid, p_org uuid, p_seller uuid) returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select case\n    when p_kind = 'signed_up' then p_target_kind = 'org' and p_target = p_org\n    when p_target_kind = 'org' then p_target = p_org\n    when p_target_kind = 'shipment' then p_target is not null and fcd.can_see_shipment(p_target)\n      and (p_seller is null or exists (select 1 from fcd.shipments s where s.id = p_target and s.shipper_org_id = p_seller))\n    when p_target_kind = 'quote_request' then p_target is not null and fcd.can_see_request(p_target)\n      and (p_seller is null or exists (select 1 from fcd.quote_requests q where q.id = p_target and q.org_id = p_seller))\n    else p_target is null\n  end\n$$;\n\ncreate policy events_insert_target on fcd.events as restrictive for insert to fcd_user\n  with check (coalesce(fcd.event_target_ok(kind, target_kind, target_id, org_id, seller_org_id), false));\n\ndo $$\ndeclare f text;\nbegin\n  foreach f in array array['shipment_outcome(uuid)', 'review_outcome(uuid)', 'review_partner(uuid)', 'partner_trust_facts(uuid[], integer)'] loop\n    execute format('revoke all on function fcd.%s from public', f);\n    execute format('grant execute on function fcd.%s to fcd_public, fcd_user', f);\n  end loop;\n  execute 'revoke all on function fcd.event_target_ok(text, text, uuid, uuid, uuid) from public';\n  execute 'grant execute on function fcd.event_target_ok(text, text, uuid, uuid, uuid) to fcd_user';\nend $$;\n" },
  { name: "0015_research.sql", sql: "-- FC도착 0015 — 셀러 인터뷰 · 먼저 검증할 실험 셋(v2 interview) — docs/research-plan.md\n--   ① research_participants   인터뷰 대상 — 운영이 넣는다. 연락처는 선택이고 화면에는 가려서\n--      research_consents      동의 여부·시각·방식(스스로/구두)·문구 판 — 쌓기만(철회도 한 줄)\n--   ② research_invites        1회용 링크 — 토큰은 sha-256 만, 만료·거두기, 응답을 끝내면 닫힘\n--   ③ research_responses      답변 — 쌓기만 한다. 진행 저장·고침은 새 판(supersedes_id), 참여자마다 한 줄기\n--   ④ research_vendor_quotes  실험 3 — 콘솔사·포워더 물량별 CBM 당 단가(운영이 넣음, 새 판)\n--   ⑤ check_funnel_events     실험 2 — /check 방문·입력·점검·보관(익명 기기 번호 해시만). fcd.events 는 조직이 필수라 따로 둔다\n--\n-- 읽기는 운영(플랫폼 관리자)만. 링크를 받은 셀러는 표 권한이 없고, 아래 security definer 함수로\n-- 자기 토큰의 자기 응답만 이어 읽고 쓴다. 데모 자료는 데모 운영 조직(is_demo) 아래 — 조직을 지우면 CASCADE.\n-- 이 파일은 자료를 지우거나 덮지 않는다.\n\n-- ① 대상 -------------------------------------------------------------------------\ncreate table fcd.research_participants (\n  id uuid primary key default gen_random_uuid(),\n  -- 조사를 하는 운영 조직(플랫폼)\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  code text not null check (code ~ '^P-[0-9]{2,4}$'),\n  -- 부르는 이름 — 실명이 아니어도 된다(「셀러 07」)\n  label text not null check (length(btrim(label)) between 1 and 60),\n  -- 선택. 화면에는 가려서 보이고, 풀어 볼 때 감사 기록이 남는다(fcd.research_contact)\n  contact text check (contact is null or length(contact) <= 120),\n  -- 모집 기준: chinaSourcing·rocketGrowth·lcl(참/거짓), monthlyShipments(정수), channel(모집 경로)\n  recruit jsonb not null default '{}'::jsonb check (jsonb_typeof(recruit) = 'object' and pg_column_size(recruit) < 2000),\n  scheduled_at timestamptz,\n  note text check (note is null or length(note) <= 400),\n  created_by uuid,\n  created_at timestamptz not null default now(),\n  unique (org_id, code)\n);\ncreate index research_participants_org_idx on fcd.research_participants (org_id, created_at desc);\n\n-- 동의 기록 — 쌓기만 한다(동의·거부·철회가 모두 한 줄씩 남는다). 지금 상태 = 가장 최근 줄\ncreate table fcd.research_consents (\n  id uuid primary key default gen_random_uuid(),\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  participant_id uuid not null references fcd.research_participants (id) on delete cascade,\n  state text not null check (state in ('agreed', 'declined', 'withdrawn')),\n  -- self = 셀러가 링크 화면에서 · verbal = 통화에서 받은 구두 동의(운영이 적음)\n  method text not null check (method in ('self', 'verbal')),\n  version text not null check (length(version) between 1 and 40),\n  created_by uuid,\n  created_at timestamptz not null default now()\n);\ncreate index research_consents_part_idx on fcd.research_consents (participant_id, created_at desc);\n\ncreate or replace function fcd.research_consent_now(p_participant uuid) returns text\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select coalesce((select c.state from fcd.research_consents c where c.participant_id = p_participant order by c.created_at desc, c.id desc limit 1), 'none')\n$$;\nrevoke all on function fcd.research_consent_now(uuid) from public;\n\n-- 연락처 가리기 — 010-****-5678 · ab***@example.com · 그 밖은 앞 두 글자만\ncreate or replace function fcd.mask_contact(p text) returns text\nlanguage sql immutable as $$\n  select case\n    when p is null or btrim(p) = '' then null\n    when p ~ '@' then left(split_part(p, '@', 1), 2) || '***@' || split_part(p, '@', 2)\n    when regexp_replace(p, '[^0-9]', '', 'g') ~ '^[0-9]{8,}$' then\n      left(regexp_replace(p, '[^0-9]', '', 'g'), 3) || '-****-' || right(regexp_replace(p, '[^0-9]', '', 'g'), 4)\n    else left(p, 2) || repeat('*', greatest(length(p) - 2, 1))\n  end\n$$;\nrevoke all on function fcd.mask_contact(text) from public;\ngrant execute on function fcd.mask_contact(text) to fcd_user;\n\n-- ② 1회용 링크 -----------------------------------------------------------------------\ncreate table fcd.research_invites (\n  id uuid primary key default gen_random_uuid(),\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  participant_id uuid not null references fcd.research_participants (id) on delete cascade,\n  token_hash text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),\n  expires_at timestamptz not null,\n  revoked_at timestamptz,\n  created_by uuid,\n  created_at timestamptz not null default now(),\n  check (expires_at > created_at)\n);\ncreate index research_invites_part_idx on fcd.research_invites (participant_id, created_at desc);\n\n-- ③ 답변 ---------------------------------------------------------------------------\ncreate table fcd.research_responses (\n  id uuid primary key default gen_random_uuid(),\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  participant_id uuid not null references fcd.research_participants (id) on delete cascade,\n  invite_id uuid references fcd.research_invites (id) on delete set null,\n  version integer not null check (version >= 1),\n  supersedes_id uuid references fcd.research_responses (id) on delete cascade,\n  -- self = 셀러가 링크로 · interviewer = 운영이 통화하며 대신 적음\n  source text not null check (source in ('self', 'interviewer')),\n  step text not null check (step in ('consent', 'lane', 'screens', 'ladder', 'habits', 'comment', 'done')),\n  completed boolean not null default false,\n  answers jsonb not null check (jsonb_typeof(answers) = 'object' and pg_column_size(answers) < 32000),\n  created_by uuid,\n  created_at timestamptz not null default now(),\n  check ((supersedes_id is null) = (version = 1)),\n  check (not completed or step = 'done')\n);\ncreate unique index research_responses_one_root on fcd.research_responses (participant_id) where supersedes_id is null;\ncreate unique index research_responses_one_successor on fcd.research_responses (supersedes_id) where supersedes_id is not null;\ncreate index research_responses_org_idx on fcd.research_responses (org_id, created_at desc);\n\ncreate view fcd.v_research_responses_current with (security_invoker = true) as\n  select r.* from fcd.research_responses r\n  where not exists (select 1 from fcd.research_responses n where n.supersedes_id = r.id);\n\n-- 새 판을 이어도 되는가: 첫 판이면 그 참여자에게 아직 판이 없고, 새 판이면 같은 참여자의 현재 판을 잇는다\ncreate or replace function fcd.research_chain_ok(p_participant uuid, p_super uuid, p_version integer) returns boolean\nlanguage sql stable security definer set search_path = fcd, pg_temp as $$\n  select case\n    when p_super is null then p_version = 1 and not exists (select 1 from fcd.research_responses r where r.participant_id = p_participant)\n    else exists (\n      select 1 from fcd.research_responses r\n      where r.id = p_super and r.participant_id = p_participant and r.version + 1 = p_version\n        and not exists (select 1 from fcd.research_responses n where n.supersedes_id = r.id))\n  end\n$$;\nrevoke all on function fcd.research_chain_ok(uuid, uuid, integer) from public;\ngrant execute on function fcd.research_chain_ok(uuid, uuid, integer) to fcd_user;\n\n-- ④ 실험 3 — 물량 단가 ---------------------------------------------------------------\ncreate table fcd.research_vendor_quotes (\n  id uuid primary key default gen_random_uuid(),\n  org_id uuid not null references fcd.orgs (id) on delete cascade,\n  -- 운영이 넣는 부르는 이름(공개하지 않음)\n  vendor_label text not null check (length(btrim(vendor_label)) between 1 and 60),\n  vendor_kind text not null check (vendor_kind in ('consolidator', 'forwarder')),\n  hub text references fcd.hubs (code),\n  port text references fcd.ports (code),\n  mode text check (mode in ('LCL', 'FERRY', 'FCL', 'AIR')),\n  -- 무엇까지 포함한 단가인가 — 다른 범위끼리는 곡선에 섞지 않는다\n  includes text not null check (includes in ('sea_cfs', 'to_port', 'to_fc')),\n  volume_cbm numeric(8, 2) not null check (volume_cbm > 0 and volume_cbm <= 10000),\n  unit_price_krw bigint not null check (unit_price_krw >= 0 and unit_price_krw <= 100000000),\n  source text not null check (source in ('call', 'email', 'quote_doc', 'other')),\n  quoted_on date not null,\n  note text check (note is null or length(note) <= 400),\n  supersedes_id uuid references fcd.research_vendor_quotes (id) on delete cascade,\n  created_by uuid,\n  created_at timestamptz not null default now()\n);\ncreate unique index research_vendor_quotes_one_successor on fcd.research_vendor_quotes (supersedes_id) where supersedes_id is not null;\ncreate index research_vendor_quotes_org_idx on fcd.research_vendor_quotes (org_id, created_at desc);\n\ncreate view fcd.v_research_vendor_quotes_current with (security_invoker = true) as\n  select v.* from fcd.research_vendor_quotes v\n  where not exists (select 1 from fcd.research_vendor_quotes n where n.supersedes_id = v.id);\n\n-- ⑤ 실험 2 — /check 퍼널 ---------------------------------------------------------------\n-- 사람을 알아보지 않는다: 브라우저가 만든 무작위 기기 번호의 sha-256 만. IP·계정·청구서 내용 없음.\n-- org_id 는 데모 자료에만 채운다(데모 운영 조직 — 걷어내기 CASCADE). 실제 방문은 비어 있다.\ncreate table fcd.check_funnel_events (\n  id uuid primary key default gen_random_uuid(),\n  org_id uuid references fcd.orgs (id) on delete cascade,\n  kind text not null check (kind in ('check_visit', 'check_input', 'check_run', 'check_saved')),\n  method text check (method in ('paste', 'excel', 'manual')),\n  visitor_hash text not null check (visitor_hash ~ '^[0-9a-f]{64}$'),\n  logged_in boolean not null default false,\n  occurred_at timestamptz not null default now()\n);\ncreate index check_funnel_kind_idx on fcd.check_funnel_events (kind, occurred_at desc);\n\n-- 권한 · RLS ------------------------------------------------------------------------\nalter table fcd.research_participants enable row level security;\nalter table fcd.research_invites enable row level security;\nalter table fcd.research_responses enable row level security;\nalter table fcd.research_vendor_quotes enable row level security;\nalter table fcd.check_funnel_events enable row level security;\n\n-- 대상: 운영만. 연락처 칸은 읽기 권한에서 뺀다(가린 값은 v_research_participants, 푼 값은 fcd.research_contact 로만)\ngrant select (id, org_id, code, label, recruit, scheduled_at, note, created_by, created_at)\n  on fcd.research_participants to fcd_user;\ngrant insert (org_id, code, label, contact, recruit, scheduled_at, note, created_by) on fcd.research_participants to fcd_user;\n-- 고치기는 일정·메모·모집 기준·연락처(지우기 포함)만. 동의는 research_consents 에 새 줄로\ngrant update (label, contact, recruit, scheduled_at, note) on fcd.research_participants to fcd_user;\ncreate policy research_participants_read on fcd.research_participants for select to fcd_user using (\n  fcd.is_platform() and fcd.org_visible(org_id)\n);\ncreate policy research_participants_insert on fcd.research_participants for insert to fcd_user with check (\n  fcd.is_platform() and fcd.is_member(org_id) and fcd.org_kind(org_id) = 'platform' and created_by = fcd.uid()\n);\ncreate policy research_participants_update on fcd.research_participants for update to fcd_user\n  using (fcd.is_platform() and fcd.org_visible(org_id))\n  with check (fcd.is_platform() and fcd.org_visible(org_id));\n\n-- 가린 연락처와 함께 보기 — 보기 주인 권한으로 돌지만 운영자에게만 줄을 낸다\ncreate view fcd.v_research_participants as\n  select p.id, p.org_id, p.code, p.label, fcd.mask_contact(p.contact) contact_masked, (p.contact is not null) has_contact,\n         p.recruit, p.scheduled_at, p.note,\n         coalesce(c.state, 'none') consent_state, c.created_at consent_at, c.method consent_method, c.version consent_version,\n         p.created_by, p.created_at, o.is_demo\n    from fcd.research_participants p join fcd.orgs o on o.id = p.org_id\n    left join lateral (\n      select x.state, x.created_at, x.method, x.version from fcd.research_consents x\n       where x.participant_id = p.id order by x.created_at desc, x.id desc limit 1\n    ) c on true\n   where fcd.is_platform() and fcd.org_visible(p.org_id);\ngrant select on fcd.v_research_participants to fcd_user;\n\n-- 연락처 풀어 보기 — 운영자만, 볼 때마다 감사 기록\ncreate or replace function fcd.research_contact(p_id uuid) returns text\nlanguage plpgsql security definer set search_path = fcd, pg_temp as $$\ndeclare c text; o uuid;\nbegin\n  if fcd.uid() is null or not fcd.is_platform() then return null; end if;\n  select contact, org_id into c, o from fcd.research_participants where id = p_id and fcd.org_visible(org_id);\n  if not found then return null; end if;\n  insert into fcd.audit_log (actor_id, org_id, action, target, detail)\n    values (fcd.uid(), o, 'research.contact_viewed', 'research_participant:' || p_id, null);\n  return c;\nend $$;\nrevoke all on function fcd.research_contact(uuid) from public;\ngrant execute on function fcd.research_contact(uuid) to fcd_user;\n\n-- 초대: 운영만. 해시 칸은 읽기 권한에서 뺀다. 고치기는 거두기(한 번, 지금 이전 시각)만\ngrant select (id, org_id, participant_id, expires_at, revoked_at, created_by, created_at) on fcd.research_invites to fcd_user;\ngrant insert (org_id, participant_id, token_hash, expires_at, created_by) on fcd.research_invites to fcd_user;\ngrant update (revoked_at) on fcd.research_invites to fcd_user;\ncreate policy research_invites_read on fcd.research_invites for select to fcd_user using (fcd.is_platform() and fcd.org_visible(org_id));\ncreate policy research_invites_insert on fcd.research_invites for insert to fcd_user with check (\n  fcd.is_platform() and fcd.is_member(org_id) and created_by = fcd.uid()\n  and exists (select 1 from fcd.research_participants p where p.id = participant_id and p.org_id = research_invites.org_id)\n);\ncreate policy research_invites_revoke on fcd.research_invites for update to fcd_user\n  using (fcd.is_platform() and fcd.org_visible(org_id) and revoked_at is null)\n  with check (revoked_at is not null and revoked_at <= now());\n\n-- 동의: 운영만 읽기. 운영이 넣는 것은 구두 동의(verbal)만 — 셀러 스스로의 동의는 아래 함수로만\nalter table fcd.research_consents enable row level security;\ngrant select, insert on fcd.research_consents to fcd_user;\ncreate policy research_consents_read on fcd.research_consents for select to fcd_user using (fcd.is_platform() and fcd.org_visible(org_id));\ncreate policy research_consents_insert on fcd.research_consents for insert to fcd_user with check (\n  fcd.is_platform() and fcd.is_member(org_id) and created_by = fcd.uid() and method = 'verbal'\n  and exists (select 1 from fcd.research_participants p where p.id = participant_id and p.org_id = research_consents.org_id)\n);\n\n-- 답변: 운영만 읽기. 운영의 쓰기는 인터뷰어 모드(대신 적기)만, 새 판으로. UPDATE·DELETE 없음\ngrant select, insert on fcd.research_responses to fcd_user;\ngrant select on fcd.v_research_responses_current to fcd_user;\ncreate policy research_responses_read on fcd.research_responses for select to fcd_user using (fcd.is_platform() and fcd.org_visible(org_id));\ncreate policy research_responses_insert on fcd.research_responses for insert to fcd_user with check (\n  fcd.is_platform() and fcd.is_member(org_id) and created_by = fcd.uid() and source = 'interviewer'\n  and exists (select 1 from fcd.research_participants p where p.id = participant_id and p.org_id = research_responses.org_id)\n  and fcd.research_chain_ok(participant_id, supersedes_id, version)\n);\n\n-- 물량 단가: 운영만. 새 판으로만(UPDATE·DELETE 없음)\ngrant select, insert on fcd.research_vendor_quotes to fcd_user;\ngrant select on fcd.v_research_vendor_quotes_current to fcd_user;\ncreate policy research_vendor_quotes_read on fcd.research_vendor_quotes for select to fcd_user using (fcd.is_platform() and fcd.org_visible(org_id));\ncreate policy research_vendor_quotes_insert on fcd.research_vendor_quotes for insert to fcd_user with check (\n  fcd.is_platform() and fcd.is_member(org_id) and created_by = fcd.uid()\n  and (supersedes_id is null or exists (\n        select 1 from fcd.research_vendor_quotes v where v.id = supersedes_id and v.org_id = research_vendor_quotes.org_id))\n);\n\n-- 퍼널: 운영만 읽기. 쓰기는 아래 함수로만(표 INSERT 권한 없음)\ngrant select on fcd.check_funnel_events to fcd_user;\ncreate policy check_funnel_read on fcd.check_funnel_events for select to fcd_user using (\n  fcd.is_platform() and (org_id is null or fcd.org_visible(org_id))\n);\n\ncreate or replace function fcd.record_check_event(p_kind text, p_method text, p_visitor text, p_logged_in boolean) returns boolean\nlanguage plpgsql security definer set search_path = fcd, pg_temp as $$\nbegin\n  if p_kind not in ('check_visit', 'check_input', 'check_run', 'check_saved') then return false; end if;\n  if p_method is not null and p_method not in ('paste', 'excel', 'manual') then return false; end if;\n  if p_visitor is null or p_visitor !~ '^[0-9a-f]{64}$' then return false; end if;\n  insert into fcd.check_funnel_events (kind, method, visitor_hash, logged_in) values (p_kind, p_method, p_visitor, coalesce(p_logged_in, false));\n  return true;\nend $$;\nrevoke all on function fcd.record_check_event(text, text, text, boolean) from public;\ngrant execute on function fcd.record_check_event(text, text, text, boolean) to fcd_public, fcd_user;\n\n-- 링크를 받은 셀러(로그인 없음)용 함수 ------------------------------------------------------\n-- 상태: open · completed · expired · revoked · not_found. 열린 링크일 때만 자기 현재 판 답변을 돌려준다.\ncreate or replace function fcd.research_invite_open(p_hash text)\nreturns table (status text, consent_state text, head_id uuid, head_version integer, step text, answers jsonb, expires_at timestamptz)\nlanguage plpgsql security definer set search_path = fcd, pg_temp as $$\ndeclare inv record; h record; st text;\nbegin\n  select i.id, i.participant_id, i.org_id, i.expires_at, i.revoked_at into inv\n    from fcd.research_invites i where i.token_hash = p_hash;\n  if not found or not fcd.org_visible(inv.org_id) then\n    return query select 'not_found'::text, null::text, null::uuid, null::integer, null::text, null::jsonb, null::timestamptz; return;\n  end if;\n  select r.id, r.version, r.step, r.answers, r.completed into h\n    from fcd.research_responses r\n   where r.participant_id = inv.participant_id and not exists (select 1 from fcd.research_responses n where n.supersedes_id = r.id);\n  st := case\n    when inv.revoked_at is not null then 'revoked'\n    when h.completed is true then 'completed'\n    when inv.expires_at <= now() then 'expired'\n    else 'open' end;\n  return query select st, fcd.research_consent_now(inv.participant_id),\n    case when st = 'open' then h.id end, case when st = 'open' then h.version end,\n    case when st = 'open' then h.step end, case when st = 'open' then h.answers end, inv.expires_at;\nend $$;\nrevoke all on function fcd.research_invite_open(text) from public;\ngrant execute on function fcd.research_invite_open(text) to fcd_public, fcd_user;\n\n-- 동의 — 열린 링크에서만. 동의하지 않으면 declined 로 적고 아무 답도 받지 않는다.\ncreate or replace function fcd.research_consent(p_hash text, p_agree boolean, p_version text) returns text\nlanguage plpgsql security definer set search_path = fcd, pg_temp as $$\ndeclare inv record;\nbegin\n  select i.id, i.participant_id, i.org_id, i.expires_at, i.revoked_at into inv from fcd.research_invites i where i.token_hash = p_hash for update;\n  if not found or not fcd.org_visible(inv.org_id) then return 'not_found'; end if;\n  if inv.revoked_at is not null then return 'revoked'; end if;\n  if inv.expires_at <= now() then return 'expired'; end if;\n  if exists (select 1 from fcd.research_responses r where r.participant_id = inv.participant_id and r.completed) then return 'completed'; end if;\n  if p_version is null or length(p_version) > 40 then return 'bad_version'; end if;\n  insert into fcd.research_consents (org_id, participant_id, state, method, version)\n    values (inv.org_id, inv.participant_id, case when p_agree then 'agreed' else 'declined' end, 'self', p_version);\n  return case when p_agree then 'ok' else 'declined' end;\nend $$;\nrevoke all on function fcd.research_consent(text, boolean, text) from public;\ngrant execute on function fcd.research_consent(text, boolean, text) to fcd_public, fcd_user;\n\n-- 진행 저장 — 열린 링크 · 동의함 · 아직 안 끝남. 참여자의 현재 판을 잇는 새 판을 넣는다(두 창이 겨루면 한쪽만 들어간다).\ncreate or replace function fcd.research_save(p_hash text, p_step text, p_answers jsonb, p_complete boolean)\nreturns table (result text, id uuid, version integer)\nlanguage plpgsql security definer set search_path = fcd, pg_temp as $$\ndeclare inv record; h record; nid uuid; nv integer;\nbegin\n  select i.id, i.participant_id, i.org_id, i.expires_at, i.revoked_at into inv from fcd.research_invites i where i.token_hash = p_hash for update;\n  if not found or not fcd.org_visible(inv.org_id) then return query select 'not_found'::text, null::uuid, null::integer; return; end if;\n  if inv.revoked_at is not null then return query select 'revoked'::text, null::uuid, null::integer; return; end if;\n  if inv.expires_at <= now() then return query select 'expired'::text, null::uuid, null::integer; return; end if;\n  if fcd.research_consent_now(inv.participant_id) <> 'agreed' then\n    return query select 'no_consent'::text, null::uuid, null::integer; return;\n  end if;\n  if p_answers is null or jsonb_typeof(p_answers) <> 'object' then return query select 'bad_answers'::text, null::uuid, null::integer; return; end if;\n  select r.id, r.version, r.completed into h from fcd.research_responses r\n   where r.participant_id = inv.participant_id and not exists (select 1 from fcd.research_responses n where n.supersedes_id = r.id);\n  if h.completed is true then return query select 'completed'::text, null::uuid, null::integer; return; end if;\n  nv := coalesce(h.version, 0) + 1;\n  insert into fcd.research_responses (org_id, participant_id, invite_id, version, supersedes_id, source, step, completed, answers)\n    values (inv.org_id, inv.participant_id, inv.id, nv, h.id, 'self',\n            case when coalesce(p_complete, false) then 'done' else p_step end, coalesce(p_complete, false), p_answers)\n    returning research_responses.id into nid;\n  return query select 'ok'::text, nid, nv;\nend $$;\nrevoke all on function fcd.research_save(text, text, jsonb, boolean) from public;\ngrant execute on function fcd.research_save(text, text, jsonb, boolean) to fcd_public, fcd_user;\n" },
];
